update public.article_cache set translation = '{"texts": ["Very large tortoises live on an island in the Indian Ocean called Aldabra, and a survey found about 180,000 of them there.", "In the 1800s, there were fewer than 1,000 tortoises, but people worked to protect them and the island became a nature reserve in 1981.", "The number of tortoises has grown greatly, and researchers said this is very good news.", "However, there are concerns — cats and rats eat tortoise eggs, the climate is also changing, and people want to keep protecting the tortoises."], "sentences": [{"text": "아주 큰 거북이들이 인도양의 섬에 살고 있어요.", "translation": "Very large turtles are living on an island in the Indian Ocean.", "vocab": [{"ko": "거북이", "en": "turtle"}, {"ko": "인도양", "en": "Indian Ocean"}, {"ko": "섬", "en": "island"}, {"ko": "살다", "en": "to live"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Shows an ongoing action or state: 살다 → 살고 있어요 ''are living''.", "example_in_sentence": "살고 있어요"}]}, {"text": "섬 이름은 알다브라예요.", "translation": "The island''s name is Aldabra.", "vocab": [{"ko": "섬", "en": "island"}, {"ko": "이름", "en": "name"}], "analysis": [{"type": "grammar", "label": "이에요/예요", "exp": "Polite ''is''. After a vowel use 예요: 알다브라 + 예요 = ''is Aldabra''.", "example_in_sentence": "알다브라예요"}]}, {"text": "조사를 했는데 거북이가 약 18만 마리 있어요.", "translation": "A survey was conducted, and there are approximately 180,000 turtles.", "vocab": [{"ko": "조사", "en": "survey; investigation"}, {"ko": "하다", "en": "to do"}, {"ko": "마리", "en": "counter for animals"}, {"ko": "있다", "en": "to exist; to have"}], "analysis": [{"type": "grammar", "label": "~는데 (background)", "exp": "Gives background before the main point: 하다 → 했는데 ''(they) did (a survey), and…''.", "example_in_sentence": "했는데"}, {"type": "grammar", "label": "~을/를", "exp": "Direct object particle. Marks the noun as the object of the preceding verb. 조사 (survey) + 를.", "example_in_sentence": "조사를"}]}, {"text": "1800년대에는 거북이가 1,000마리도 없었어요.", "translation": "In the 1800s, there were not even 1,000 turtles.", "vocab": [{"ko": "1800년대", "en": "1800s"}, {"ko": "없다", "en": "to not exist; to not have"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense marker for completed action or state. 없다 (to not exist) + 었어요 → 없었어요.", "example_in_sentence": "없었어요"}, {"type": "grammar", "label": "~도", "exp": "Particle indicating emphasis or ''even''. Shows that even 1,000 turtles did not exist. 1,000마리 + 도.", "example_in_sentence": "1,000마리도"}]}, {"text": "그런데 사람들이 거북이를 지켜줬어요.", "translation": "However, people protected the turtles.", "vocab": [{"ko": "사람", "en": "person; people"}, {"ko": "거북이", "en": "turtle"}, {"ko": "지키다", "en": "to protect; to guard"}], "analysis": [{"type": "grammar", "label": "~아/어주다", "exp": "Auxiliary verb expressing action done for someone''s benefit or as a favor. 지키다 (to protect) + 어주다 → 지켜줬어요 (past tense).", "example_in_sentence": "지켜줬어요"}]}, {"text": "1981년에 이 섬은 자연 보호 구역이 됐어요.", "translation": "In 1981, this island became a nature conservation area.", "vocab": [{"ko": "자연", "en": "nature"}, {"ko": "보호", "en": "protection"}, {"ko": "구역", "en": "area; zone"}, {"ko": "되다", "en": "to become"}], "analysis": [{"type": "grammar", "label": "~이/가 되다", "exp": "''To become N'': 구역 + 이 되다 → 구역이 됐어요 ''became a (protected) area''.", "example_in_sentence": "구역이 됐어요"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense marker. 되다 (to become) + 었어요 → 됐어요.", "example_in_sentence": "됐어요"}]}, {"text": "지금은 거북이 수가 많이 늘었어요.", "translation": "Now the number of turtles has increased a lot.", "vocab": [{"ko": "지금", "en": "now"}, {"ko": "수", "en": "number; quantity"}, {"ko": "늘다", "en": "to increase; to grow"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense marker. 늘다 (to increase) + 었어요 → 늘었어요.", "example_in_sentence": "늘었어요"}]}, {"text": "연구자들은 이것이 아주 좋은 소식이라고 했어요.", "translation": "Researchers said this is very good news.", "vocab": [{"ko": "연구자", "en": "researcher"}, {"ko": "소식", "en": "news"}, {"ko": "좋다", "en": "to be good"}], "analysis": [{"type": "grammar", "label": "~(이)라고 하다", "exp": "Reports what someone said: 좋은 소식이다 → 좋은 소식이라고 했어요 ''said (it) was good news''.", "example_in_sentence": "좋은 소식이라고"}, {"type": "grammar", "label": "~았/었/였어요", "exp": "Past polite. 하다 → 했어요 ''said''.", "example_in_sentence": "했어요"}]}, {"text": "하지만 걱정도 있어요.", "translation": "However, there is also concern.", "vocab": [{"ko": "걱정", "en": "concern; worry"}, {"ko": "있다", "en": "to exist; to have"}], "analysis": [{"type": "grammar", "label": "~도", "exp": "Particle indicating ''also'' or ''as well''. Shows additional concern alongside good news. 걱정 + 도.", "example_in_sentence": "걱정도"}]}, {"text": "고양이와 쥐가 거북이 알을 먹어요.", "translation": "Cats and rats eat turtle eggs.", "vocab": [{"ko": "고양이", "en": "cat"}, {"ko": "쥐", "en": "rat; mouse"}, {"ko": "알", "en": "egg"}, {"ko": "먹다", "en": "to eat"}], "analysis": [{"type": "grammar", "label": "~과/와", "exp": "Coordinating conjunction particle joining nouns. 고양이 (cat) + 와 + 쥐 (rat).", "example_in_sentence": "고양이와"}]}, {"text": "날씨도 변하고 있어요.", "translation": "The weather is also changing.", "vocab": [{"ko": "날씨", "en": "weather"}, {"ko": "변하다", "en": "to change"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect marker indicating ongoing action. 변하다 (to change) + 고 있어요.", "example_in_sentence": "변하고 있어요"}]}, {"text": "사람들은 거북이를 계속 지키고 싶어 해요.", "translation": "People want to continue protecting turtles.", "vocab": [{"ko": "사람", "en": "person; people"}, {"ko": "거북이", "en": "turtle"}, {"ko": "계속", "en": "continually; continuously"}, {"ko": "지키다", "en": "to protect; to guard"}], "analysis": [{"type": "grammar", "label": "~고 싶어 하다", "exp": "''Want to'' for other people (not I/you): 지키다 → 지키고 싶어 해요 ''want to protect''.", "example_in_sentence": "지키고 싶어 해요"}]}], "version": "s6"}', vocab = '[{"ko": "거북이", "en": "turtle", "note": ""}, {"ko": "인도양", "en": "Indian Ocean", "note": ""}, {"ko": "섬", "en": "island", "note": ""}, {"ko": "살다", "en": "to live", "note": ""}, {"ko": "이름", "en": "name", "note": ""}, {"ko": "조사", "en": "survey; investigation", "note": ""}, {"ko": "하다", "en": "to do", "note": ""}, {"ko": "마리", "en": "counter for animals", "note": ""}, {"ko": "있다", "en": "to exist; to have", "note": ""}, {"ko": "1800년대", "en": "1800s", "note": ""}, {"ko": "없다", "en": "to not exist; to not have", "note": ""}, {"ko": "사람", "en": "person; people", "note": ""}, {"ko": "지키다", "en": "to protect; to guard", "note": ""}, {"ko": "자연", "en": "nature", "note": ""}, {"ko": "보호", "en": "protection", "note": ""}, {"ko": "구역", "en": "area; zone", "note": ""}, {"ko": "되다", "en": "to become", "note": ""}, {"ko": "지금", "en": "now", "note": ""}, {"ko": "수", "en": "number; quantity", "note": ""}, {"ko": "늘다", "en": "to increase; to grow", "note": ""}, {"ko": "연구자", "en": "researcher", "note": ""}, {"ko": "소식", "en": "news", "note": ""}, {"ko": "좋다", "en": "to be good", "note": ""}, {"ko": "걱정", "en": "concern; worry", "note": ""}, {"ko": "고양이", "en": "cat", "note": ""}, {"ko": "쥐", "en": "rat; mouse", "note": ""}, {"ko": "알", "en": "egg", "note": ""}, {"ko": "먹다", "en": "to eat", "note": ""}, {"ko": "날씨", "en": "weather", "note": ""}, {"ko": "변하다", "en": "to change", "note": ""}, {"ko": "계속", "en": "continually; continuously", "note": ""}]', grammar = '{"patterns": [{"name": "~고 있어요", "level": "Starter", "exp": "Progressive aspect marker indicating ongoing action. 변하다 (to change) + 고 있어요.", "ex_ko": "아주 큰 거북이들이 인도양의 섬에 살고 있어요.", "ex_en": "Very large turtles are living on an island in the Indian Ocean."}, {"name": "이에요/예요", "level": "Starter", "exp": "Polite ''is''. After a vowel use 예요: 알다브라 + 예요 = ''is Aldabra''.", "ex_ko": "섬 이름은 알다브라예요.", "ex_en": "The island''s name is Aldabra."}, {"name": "~는데 (background)", "level": "Starter", "exp": "Gives background before the main point: 하다 → 했는데 ''(they) did (a survey), and…''.", "ex_ko": "조사를 했는데 거북이가 약 18만 마리 있어요.", "ex_en": "A survey was conducted, and there are approximately 180,000 turtles."}, {"name": "~을/를", "level": "Starter", "exp": "Direct object particle. Marks the noun as the object of the preceding verb. 조사 (survey) + 를.", "ex_ko": "조사를 했는데 거북이가 약 18만 마리 있어요.", "ex_en": "A survey was conducted, and there are approximately 180,000 turtles."}, {"name": "~았/었어요", "level": "Starter", "exp": "Past tense marker for completed action or state. 없다 (to not exist) + 었어요 → 없었어요.", "ex_ko": "1800년대에는 거북이가 1,000마리도 없었어요.", "ex_en": "In the 1800s, there were not even 1,000 turtles."}, {"name": "~도", "level": "Starter", "exp": "Particle indicating emphasis or ''even''. Shows that even 1,000 turtles did not exist. 1,000마리 + 도.", "ex_ko": "1800년대에는 거북이가 1,000마리도 없었어요.", "ex_en": "In the 1800s, there were not even 1,000 turtles."}, {"name": "~아/어주다", "level": "Starter", "exp": "Auxiliary verb expressing action done for someone''s benefit or as a favor. 지키다 (to protect) + 어주다 → 지켜줬어요 (past tense).", "ex_ko": "그런데 사람들이 거북이를 지켜줬어요.", "ex_en": "However, people protected the turtles."}, {"name": "~이/가 되다", "level": "Starter", "exp": "''To become N'': 구역 + 이 되다 → 구역이 됐어요 ''became a (protected) area''.", "ex_ko": "1981년에 이 섬은 자연 보호 구역이 됐어요.", "ex_en": "In 1981, this island became a nature conservation area."}, {"name": "~(이)라고 하다", "level": "Starter", "exp": "Reports what someone said: 좋은 소식이다 → 좋은 소식이라고 했어요 ''said (it) was good news''.", "ex_ko": "연구자들은 이것이 아주 좋은 소식이라고 했어요.", "ex_en": "Researchers said this is very good news."}, {"name": "~았/었/였어요", "level": "Starter", "exp": "Past polite. 하다 → 했어요 ''said''.", "ex_ko": "연구자들은 이것이 아주 좋은 소식이라고 했어요.", "ex_en": "Researchers said this is very good news."}, {"name": "~과/와", "level": "Starter", "exp": "Coordinating conjunction particle joining nouns. 고양이 (cat) + 와 + 쥐 (rat).", "ex_ko": "고양이와 쥐가 거북이 알을 먹어요.", "ex_en": "Cats and rats eat turtle eggs."}, {"name": "~고 싶어 하다", "level": "Starter", "exp": "''Want to'' for other people (not I/you): 지키다 → 지키고 싶어