update public.article_cache set translation = '{"texts": ["Honey Ross (28), daughter of British TV presenter Jonathan Ross, is learning Welsh using the Duolingo app.", "Her boyfriend Gav Murphy (41) is originally from Wales. The two met on Instagram and quickly bonded over their shared love of films.", "The couple live in London, so opportunities to practise Welsh are limited. Murphy encourages Honey to speak Welsh to their dog, Coco.", "Murphy said, ''Coco won''t tell you if you''re wrong.'' He also said Honey''s excellent memory helps her when learning a new language.", "Honey is a writer and podcaster. In 2017, she co-founded the Pink Protest movement for women''s rights, which succeeded in securing UK government funding.", "Murphy gets on well with Honey''s father Jonathan Ross, as they both love to laugh. Murphy enjoys hearing Jonathan''s stories about the many famous people he has met."], "sentences": [{"text": "영국 방송인 조나단 로스의 딸 허니 로스(28세)가 웨일스어를 배우고 있어요.", "translation": "Honey Ross (28), daughter of British broadcaster Jonathan Ross, is learning Welsh.", "vocab": [{"ko": "방송인", "en": "broadcaster"}, {"ko": "딸", "en": "daughter"}, {"ko": "배우다", "en": "to learn"}], "analysis": []}, {"text": "허니는 듀오링고 앱으로 공부하고 있어요.", "translation": "Honey is studying using the Duolingo app.", "vocab": [{"ko": "앱", "en": "app"}, {"ko": "공부하다", "en": "to study"}], "analysis": [{"type": "grammar", "label": "~으로", "exp": "Instrumental particle marking the means or tool used to perform an action.", "example_in_sentence": "앱으로"}]}, {"text": "허니의 남자 친구 개브 머피(41세)는 웨일스 출신이에요.", "translation": "Honey''s boyfriend Gabe Murphy (age 41) is from Wales.", "vocab": [{"ko": "남자 친구", "en": "boyfriend"}, {"ko": "출신", "en": "origin; native of"}], "analysis": []}, {"text": "두 사람은 인스타그램에서 만났고, 영화를 좋아해서 금방 친해졌어요.", "translation": "The two met on Instagram, and because they both liked movies, they quickly became close.", "vocab": [{"ko": "만나다", "en": "to meet"}, {"ko": "영화", "en": "movie"}, {"ko": "좋아하다", "en": "to like"}, {"ko": "금방", "en": "quickly; soon"}], "analysis": [{"type": "grammar", "label": "~았고", "exp": "Conjunctive ending for past tense. Connects two clauses; second clause typically provides additional information or consequence.", "example_in_sentence": "만났고"}, {"type": "grammar", "label": "~아/어서", "exp": "Causal/reason connector: ''because'' or ''so''. Indicates reason for action in following clause.", "example_in_sentence": "좋아해서"}, {"type": "grammar", "label": "~아/어지다", "exp": "Shows a change of state: 친하다 ''to be close'' → 친해지다 ''to become close'' → 친해졌어요.", "example_in_sentence": "친해졌어요"}]}, {"text": "두 사람은 런던에 살고 있어요.", "translation": "The two live in London.", "vocab": [{"ko": "살다", "en": "to live"}], "analysis": []}, {"text": "그래서 웨일스어를 연습할 기회가 많지 않아요.", "translation": "So she doesn''t have many chances to practice Welsh.", "vocab": [{"ko": "연습하다", "en": "to practice"}, {"ko": "기회", "en": "opportunity"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ (noun modifier)", "exp": "Prospective modifier for ''to do'': 연습하다 → 연습할 기회 ''a chance to practice''.", "example_in_sentence": "연습할"}, {"type": "grammar", "label": "~지 않다", "exp": "Negative ''not'': 많다 → 많지 않아요 ''are not many''.", "example_in_sentence": "많지 않아요"}]}, {"text": "머피는 허니에게 두 사람의 강아지 코코에게 웨일스어로 말해 보라고 해요.", "translation": "Murphy tells Honey to try speaking Welsh to their dog Coco.", "vocab": [{"ko": "강아지", "en": "dog"}, {"ko": "말하다", "en": "to speak"}], "analysis": [{"type": "grammar", "label": "~에게", "exp": "Dative particle marking indirect object or recipient of action.", "example_in_sentence": "허니에게"}, {"type": "grammar", "label": "~(으)로", "exp": "Instrumental particle marking language or tool used.", "example_in_sentence": "웨일스어로"}, {"type": "grammar", "label": "~아/어 보다", "exp": "Auxiliary expressing attempted action or trying something out. Here: ''말해 보다'' = try speaking.", "example_in_sentence": "말해 보라고"}, {"type": "grammar", "label": "~(으)라고 하다", "exp": "Reports a command or suggestion: 말해 보다 → 말해 보라고 해요 ''tells (her) to try speaking''.", "example_in_sentence": "말해 보라고 해요"}]}, {"text": "머피는 \"코코는 틀려도 뭐라고 하지 않으니까요\"라고 말했어요.", "translation": "Murphy said, \"Coco won''t say anything even if you make mistakes.\"", "vocab": [{"ko": "틀리다", "en": "to make a mistake"}, {"ko": "뭐라고 하다", "en": "to say something; to criticize"}], "analysis": [{"type": "grammar", "label": "~어도", "exp": "Concessive marker meaning ''even if'' or ''although''. Marks condition that doesn''t prevent main action.", "example_in_sentence": "틀려도"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation form combining negation marker ~지 with ~않다.", "example_in_sentence": "하지 않으니까"}, {"type": "grammar", "label": "~(으)니까", "exp": "Reason ''because''. After a consonant use 으니까: 않다 → 않으니까. Ending a sentence with ~니까요 gives the reason on its own.", "example_in_sentence": "않으니까"}]}, {"text": "허니는 기억력이 아주 좋아서 언어 공부에 도움이 된다고 해요.", "translation": "Honey says she has a very good memory, which helps her study languages.", "vocab": [{"ko": "기억력", "en": "memory"}, {"ko": "아주", "en": "very"}, {"ko": "도움", "en": "help"}, {"ko": "되다", "en": "to become (도움이 되다 = to help)"}], "analysis": [{"type": "grammar", "label": "~아/어서", "exp": "Causal connector. Indicates reason why language study becomes helpful.", "example_in_sentence": "좋아서"}, {"type": "expression", "label": "도움이 되다", "exp": "''To be helpful'': 도움 ''help'' + 이 되다. 도움이 된다고 해요 = ''(she) says it helps''.", "example_in_sentence": "도움이 된다고"}]}, {"text": "허니는 작가이고 팟캐스터이기도 해요.", "translation": "Honey is a writer and also a podcaster.", "vocab": [{"ko": "작가", "en": "writer"}, {"ko": "팟캐스터", "en": "podcaster"}], "analysis": [{"type": "grammar", "label": "~이고", "exp": "''Is N and…'': 작가이다 → 작가이고 ''is a writer and''.", "example_in_sentence": "작가이고"}, {"type": "grammar", "label": "~이기도 하다", "exp": "''Is also N'': 팟캐스터이다 → 팟캐스터이기도 해요 ''is also a podcaster''.", "example_in_sentence": "팟캐스터이기도 해요"}]}, {"text": "그녀는 2017년에 여성 권리를 위한 핑크 프로테스트 운동을 함께 만들었어요.", "translation": "She co-created the Pink Protest movement for women''s rights in 2017.", "vocab": [{"ko": "여성", "en": "woman"}, {"ko": "권리", "en": "right"}, {"ko": "운동", "en": "movement"}, {"ko": "만들다", "en": "to create"}], "analysis": [{"type": "grammar", "label": "~을/를 위한", "exp": "Purpose/beneficiary marker. ''~을/를 위하다'' = to be for. Here forms modifier ''~을/를 위한''.", "example_in_sentence": "권리를 위한"}]}, {"text": "이 운동은 영국 정부에서 지원을 받는 데 성공했어요.", "translation": "This movement succeeded in receiving support from the British government.", "vocab": [{"ko": "정부", "en": "government"}, {"ko": "지원", "en": "support"}, {"ko": "받다", "en": "to receive"}, {"ko": "성공하다", "en": "to succeed"}], "analysis": [{"type": "grammar", "label": "~는 데 성공하다", "exp": "''Succeed in doing'': 받다 → 받는 데 성공했어요 ''succeeded in getting (support)''.", "example_in_sentence": "받는 데 성공했어요"}]}, {"text": "머피는 허니의 아버지 조나단 로스와도 사이가 좋아요.", "translation": "Murphy also has a good relationship with Honey''s father Jonathan Ross.", "vocab": [{"ko": "아버지", "en": "father"}, {"ko": "사이", "en": "relationship; between"}], "analysis": [{"type": "grammar", "label": "~와도", "exp": "Particle combining ~와 (with) + ~도 (also). Marks inclusive/emphatic co-participant.", "example_in_sentence": "로스와도"}, {"type": "expression", "label": "사이가 좋다", "exp": "Idiomatic expression meaning ''to have a good relationship''. Relationship + good.", "example_in_sentence": "사이가 좋아요"}]}, {"text": "두 사람 모두 웃음을 좋아하기 때문이에요.", "translation": "It is because both of them like laughter.", "vocab": [{"ko": "모두", "en": "both; all"}, {"ko": "웃음", "en": "laughter"}], "analysis": [{"type": "grammar", "label": "~기 때문이다", "exp": "''It''s because…'': 좋아하다 → 좋아하기 때문이에요 ''it''s because (they) like''.", "example_in_sentence": "좋아하기 때문이에요"}]}, {"text": "머피는 조나단이 많은 유명한 사람들을 만났기 때문에, 그 이야기를 듣고 싶어 해요.", "translation": "Murphy wants to hear those stories because Jonathan has met many famous people.", "vocab": [{"ko": "많다", "en": "to be many; to be a lot"}, {"ko": "유명하다", "en": "to be famous"}, {"ko": "사람", "en": "person"}, {"ko": "이야기", "en": "story"}], "analysis": [{"type": "grammar", "label": "~기 때문에", "exp": "''Because'': 만나다 → 만났기 때문에 ''because (he) has met''.", "example_in_sentence": "만났기 때문에"}, {"type": "grammar", "label": "~고 싶어 하다", "exp": "''Want to'' for a third person: 듣다 → 듣고 싶어 해요 ''wants to hear''.", "example_in_sentence": "듣고 싶어 해요"}]}], "version": "s6"}', vocab = '[{"ko": "방송인", "en": "broadcaster", "note": ""}, {"ko": "딸", "en": "daughter", "note": ""}, {"ko": "배우다", "en": "to learn", "note": ""}, {"ko": "앱", "en": "app", "note": ""}, {"ko": "공부하다", "en": "to study", "note": ""}, {"ko": "남자 친구", "en": "boyfriend", "note": ""}, {"ko": "출신", "en": "origin; native of", "note": ""}, {"ko": "만나다", "en": "to meet", "note": ""}, {"ko": "영화", "en": "movie", "note": ""}, {"ko": "좋아하다", "en": "to like", "note": ""}, {"ko": "금방", "en": "quickly; soon", "note": ""}, {"ko": "살다", "en": "to live", "note": ""}, {"ko": "연습하다", "en": "to practice", "note": ""}, {"ko": "기회", "en": "opportunity", "note": ""}, {"ko": "강아지", "en": "dog", "note": ""}, {"ko": "말하다", "en": "to speak", "note": ""}, {"ko": "틀리다", "en": "to make a mistake", "note": ""}, {"ko": "뭐라고 하다", "en": "to say something; to criticize", "note": ""}, {"ko": "기억력", "en": "memory", "note": ""}, {"ko": "아주", "en": "very", "note": ""}, {"ko": "도움", "en": "help", "note": ""}, {"ko": "되다", "en": "to become (도움이 되다 = to help)", "note": ""}, {"ko": "작가", "en": "writer", "note": ""}, {"ko": "팟캐스터", "en": "podcaster", "note": ""}, {"ko": "여성", "en": "woman", "note": ""}, {"ko": "권리", "en": "right", "note": ""}, {"ko": "운동", "en": "movement", "note": ""}, {"ko": "만들다", "en": "to create", "note": ""}, {"ko": "정부", "en": "government", "note": ""}, {"ko": "지원", "en": "support", "note": ""}, {"ko": "받다", "en": "to receive", "note": ""}, {"ko": "성공하다", "en": "to succeed", "note": ""}, {"ko": "아버지", "en": "father", "note": ""}, {"ko": "사이", "en": "relationship; between", "note": ""}, {"ko": "모두", "en": "both; all", "note": ""}, {"ko": "웃음", "en": "laughter", "note": ""}, {"ko": "많다", "en": "to be many; to be a lot", "note": ""}, {"ko": "유명하다", "en": "to be famous", "note": ""}, {"ko": "사람", "en": "person", "note": ""}, {"ko": "이야기", "en": "story", "note": ""}]', grammar = '{"patterns": [{"name": "~으로", "level": "Intermediate", "exp": "Instrumental particle marking the means or tool used to perform an action.", "ex_ko": "허니는 듀오링고 앱으로 공부하고 있어요.", "ex_en": "Honey is studying using the Duolingo app."}, {"name": "~았고", "level": "Intermediate", "exp": "Conjunctive ending for past tense. Connects two clauses; second clause typically provides additional information or consequence.", "ex_ko": "두 사람은 인스타그램에서 만났고, 영화를 좋아해서 금방 친해졌어요.", "ex_en": "The two met on Instagram, and because they both liked movies, they quickly became close."}, {"name": "~아/어서", "level": "Intermediate", "exp": "Causal/reason connector: ''because'' or ''so''. Indicates reason for action in following clause.", "ex_ko": "두 사람은 인스타그램에서 만났고, 영화를 좋아해서 금방 친해졌어요.", "ex_en": "The two met on Instagram, and because they both liked movies, they quickly became close."}, {"name": "~아/어지다", "level": "Intermediate", "exp": "Shows a change of state: 친하다 ''to be close'' → 친해지다 ''to become close'' → 친해졌어요.", "ex_ko": "두 사람은 인스타그램에서 만났고, 영화를 좋아해서 금방 친해졌어요.", "ex_en": "The two met on Instagram, and because they both liked movies, they quickly became close."}, {"name": "~(으)ㄹ (noun modifier)", "level": "Intermediate", "exp": "Prospective modifier for ''to do'': 연습하다 → 연습할 기회 ''a chance to practice''.", "ex_ko": "그래서 웨일스어를 연습할 기회가 많지 않아요.", "ex_en": "So she doesn''t have many chances to practice Welsh."}, {"name": "~지 않다", "level": "Intermediate", "exp": "Negation form combining negation marker ~지 with ~않다.", "ex_ko": "그래서 웨일스어를 연습할 기회가 많지 않아요.", "ex_en": "So she doesn''t have many chances to practice Welsh."}, {"name": "~에게", "level": "Intermediate", "exp": "Dative particle marking indirect object or recipient of action.", "ex_ko": "머피는 허니에게 두 사람의 강아지 코코에게 웨일스어로 말해 보라고 해요.", "ex_en": "Murphy tells Honey to try speaking Welsh to their dog Coco."}, {"name": "~(으)로", "level": "Intermediate", "exp": "Instrumental particle marking language or tool used.", "ex_ko": "머피는 허니에게 두 사람의 강아지 코코에게 웨일스어로 말해 보라고 해요.", "ex_en": "Murphy tells Honey to try speaking Welsh to their dog Coco."}, {"name": "~아/어 보다", "level": "Intermediate", "exp": "Auxiliary expressing attempted action or trying something out. Here: ''말해 보다'' = try speaking.", "ex_ko": "머피는 허니에게 두 사람의 강아지 코코에게 웨일스어로 말해 보라고 해요.", "ex_en": "Murphy tells Honey to try speaking Welsh to their dog Coco."}, {"name": "~(으)라고 하다", "level": "Intermediate", "exp": "Reports a command or suggestion: 말해 보다 → 말해 보라고 해요 ''tells (her) to try speaking''.", "ex_ko": "머피는 허니에게 두 사람의 강아지 코코에게 웨일스어로 말해 보라고 해요.", "ex_en": "Murphy tells Honey to try speaking Welsh to their dog Coco."}, {"name": "~어도", "level": "Intermediate", "exp": "Concessive marker meaning ''even if'' or ''although''. Marks condition that doesn''t prevent main action.", "ex_ko": "머피는 \"코코는 틀려도 뭐라고 하지 않으니까요\"라고 말했어요.", "ex_en": "Murphy said, \"Coco won''t say anything even if you make mistakes.\""}, {"name": "~(으)니까", "level": "Intermediate", "exp": "Reason ''because''. After a consonant use 으니까: 않다 → 않으니까. Ending a sentence with ~니까요 gives the reason on its own.", "ex_ko": "머피는 \"코코는 틀려도 뭐라고 하지 않으니까요\"라고 말했어요.", "ex_en": "Murphy said, \"Coco won''t say anything even if you make mistakes.\""}, {"name": "~이고", "level": "Intermediate", "exp": "''Is N and…'': 작가이다 → 작가이고 ''is a writer and''.", "ex_ko": "허니는 작가이고 팟캐스터이기도 해요.", "ex_en": "Honey is a writer and also a podcaster."}, {"name": "~이기도 하다", "level": "Intermediate", "exp": "''Is also N'': 팟캐스터이다 → 팟캐스터이기도 해요 ''is also a podcaster''.", "ex_ko": "허니는 작가이고 팟캐스터이기도 해요.", "ex_en": "Honey is a writer and also a podcaster."}, {"name": "~을/를 위한", "level": "Intermediate", "exp": "Purpose/beneficiary marker. ''~을/를 위하다'' = to be for. Here forms modifier ''~을/를 위한''.", "ex_ko": "그녀는 2017년에 여성 권리를 위한 핑크 프로테스트 운동을 함께 만들었어요.", "ex_en": "She co-created the Pink Protest movement for women''s rights in 2017."}]}', updated_at = now() where article_id = 'mv4bhj5iqpcy' and md5(translation) = 'bcdd992c8ffd34d8263cff9f43759431';
update public.article_cache set translation = '{"texts": ["Billboard released its World Albums chart dated October 10. &TEAM''s mini album ''Mark on Me'' re-entered the chart at No. 1, marking the first time the group has ever topped it. The album also debuted in the top 20 of the Billboard 200, setting a new personal best for &TEAM.", "Stray Kids'' latest mini album ''THIS & THAT'' dropped to No. 2 in its eighth week after six non-consecutive weeks at No. 1, while holding steady at No. 34 on the Billboard 200. The group''s 2025 album ''KARMA'' also climbed back to No. 23 in its 55th week on the chart.", "ENHYPEN''s mini album ''THE SIN : BLISS'' rose to No. 3 in its sixth week, also climbing back to No. 161 on the Billboard 200. ILLIT''s ''MAMIHLAPINATAPAI'' reached No. 6 in its 22nd week, continuing its steady presence on the chart.", "BTS''s anthology album ''Proof'' jumped to No. 7 in its 225th week on the chart. EVAN (Heeseung)''s debut mini album ''DEATH OF ME'' took No. 8 in its fourth week, while LE SSERAFIM''s ''PUREFLOW'' rose to No. 11 in its 19th week.", "ATEEZ''s ''GOLDEN HOUR : Part.5'' held at No. 14, aespa''s ''LEMONADE'' came in at No. 18, and NewJeans'' ''Get Up'' ranked No. 19 in its 160th week on the chart."], "sentences": [{"text": "빌보드가 10월 10일 자 월드 앨범 차트를 발표했습니다.", "translation": "Billboard announced the World Album Chart dated October 10.", "vocab": [{"ko": "발표하다", "en": "to announce; to publish"}], "analysis": []}, {"text": "이번 주 &TEAM의 미니 앨범 ''Mark on Me''가 차트 1위에 재진입하면서 그룹 역사상 처음으로 1위를 차지하게 되었습니다.", "translation": "&TEAM''s mini album ''Mark on Me'' re-entered the chart at number 1 this week, marking the first time the group has achieved number 1 status in their history.", "vocab": [{"ko": "재진입하다", "en": "to re-enter"}, {"ko": "차지하다", "en": "to take; to occupy; to claim"}], "analysis": [{"type": "grammar", "label": "~면서", "exp": "Connective ending indicating concurrent or sequential actions. Shows that re-entering and achieving 1st place happen together.", "example_in_sentence": "재진입하면서"}, {"type": "grammar", "label": "~게 되다", "exp": "Auxiliary verb phrase expressing a change of state or realization. 차지하다 + 게 되다 indicates the group came to achieve 1st place (passive realization).", "example_in_sentence": "차지하게 되었습니다"}]}, {"text": "이 앨범은 빌보드 200에서도 상위 20위 안에 데뷔하며 &TEAM의 최고 순위를 기록했습니다.", "translation": "This album also debuted within the top 20 on the Billboard 200, recording &TEAM''s highest ranking.", "vocab": [{"ko": "데뷔하다", "en": "to debut; to make a first appearance"}, {"ko": "기록하다", "en": "to record; to mark"}], "analysis": [{"type": "grammar", "label": "~(으)며", "exp": "Written connector ''and / while'': 데뷔하다 → 데뷔하며 ''debuted (in the top 20) and…''.", "example_in_sentence": "데뷔하며"}]}, {"text": "스트레이 키즈의 최신 미니 앨범 ''THIS & THAT''은 여섯 번의 비연속 1위를 기록한 후 이번 주 2위로 내려왔습니다.", "translation": "Stray Kids'' latest mini album ''THIS & THAT'' has dropped to number 2 this week after recording six non-consecutive number 1s.", "vocab": [{"ko": "비연속", "en": "non-consecutive; discontinuous"}, {"ko": "내려오다", "en": "to come down; to drop (in ranking)"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 후(에)", "exp": "''After doing'': 기록하다 → 기록한 후 ''after recording''.", "example_in_sentence": "기록한 후"}]}, {"text": "차트에 오른 지 8주째이며, 빌보드 200에서는 34위를 유지하고 있습니다.", "translation": "It is in its 8th week on the chart, and is maintaining 34th place on the Billboard 200.", "vocab": [{"ko": "유지하다", "en": "to maintain; to keep"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 지 N째", "exp": "''It has been N since…'': 오르다 → 오른 지 8주째 ''the 8th week since it entered (the chart)''.", "example_in_sentence": "오른 지 8주째"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect marker. Verb 유지하다 + 고 있다 shows ongoing/habitual action in present.", "example_in_sentence": "유지하고 있습니다"}]}, {"text": "같은 그룹의 2025년 앨범 ''KARMA''는 55주째에 23위로 다시 올라왔습니다.", "translation": "The same group''s 2025 album ''KARMA'' has risen again to 23rd place in its 55th week.", "vocab": [{"ko": "올라오다", "en": "to come up; to rise (in ranking)"}], "analysis": [{"type": "expression", "label": "~로 다시 올라오다", "exp": "Expression indicating a return to or recovery of a higher ranking position after falling.", "example_in_sentence": "23위로 다시 올라왔습니다"}]}, {"text": "ENHYPEN의 미니 앨범 ''THE SIN : BLISS''는 6주째에 3위로 상승했습니다.", "translation": "ENHYPEN''s mini album ''THE SIN : BLISS'' has risen to 3rd place in its 6th week.", "vocab": [{"ko": "상승하다", "en": "to rise; to go up"}], "analysis": []}, {"text": "빌보드 200에서도 161위로 다시 올라오면서 두 차트 모두에서 순위가 높아졌습니다.", "translation": "On the Billboard 200, it also rose again to 161st place, with rankings improving on both charts.", "vocab": [{"ko": "높아지다", "en": "to become high; to improve (of ranking)"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "''While / as'': 올라오다 → 올라오면서 ''as it climbed back (to 161st)''.", "example_in_sentence": "올라오면서"}]}, {"text": "ILLIT의 ''MAMIHLAPINATAPAI''는 22주째에 6위에 오르면서 꾸준히 차트에 머물고 있습니다.", "translation": "ILLIT''s ''MAMIHLAPINATAPAI'' has risen to 6th place in its 22nd week, steadily remaining on the chart.", "vocab": [{"ko": "꾸준히", "en": "steadily; consistently"}, {"ko": "머물다", "en": "to stay; to remain"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect marker. 머물다 + 고 있다 indicates the ongoing state of remaining on the chart.", "example_in_sentence": "머물고 있습니다"}]}, {"text": "BTS의 앤솔로지 앨범 ''Proof''는 225주째에 7위로 뛰어올랐습니다.", "translation": "BTS''s anthology album ''Proof'' has jumped to 7th place in its 225th week.", "vocab": [{"ko": "뛰어오르다", "en": "to jump (up); to leap; to surge"}], "analysis": []}, {"text": "EVAN(히승)의 첫 미니 앨범 ''DEATH OF ME''는 4주째에 8위를 차지했으며, LE SSERAFIM의 ''PUREFLOW''는 19주째에 11위로 상승했습니다.", "translation": "EVAN(Hiseung)''s first mini album ''DEATH OF ME'' has claimed 8th place in its 4th week, and LE SSERAFIM''s ''PUREFLOW'' has risen to 11th place in its 19th week.", "vocab": [{"ko": "차지하다", "en": "to take; to occupy; to claim"}], "analysis": [{"type": "grammar", "label": "~(으)며", "exp": "Written connector ''and'': 차지했다 → 차지했으며 ''took (8th place), and…''.", "example_in_sentence": "차지했으며"}]}, {"text": "이 밖에 ATEEZ의 ''GOLDEN HOUR : Part.5''가 14위를 유지했고, aespa의 ''LEMONADE''는 18위, 뉴진스의 ''Get Up''은 160주째에 19위를 기록했습니다.", "translation": "Beyond this, ATEEZ''s ''GOLDEN HOUR : Part.5'' has maintained 14th place, aespa''s ''LEMONADE'' is at 18th, and NewJeans'' ''Get Up'' has recorded 19th place in its 160th week.", "vocab": [{"ko": "유지하다", "en": "to maintain; to keep"}], "analysis": [{"type": "expression", "label": "이 밖에", "exp": "Expression meaning ''besides this; furthermore; in addition to.'' Lists additional information outside the previous content.", "example_in_sentence": "이 밖에"}]}], "version": "s6"}', vocab = '[{"ko": "발표하다", "en": "to announce; to publish", "note": ""}, {"ko": "재진입하다", "en": "to re-enter", "note": ""}, {"ko": "차지하다", "en": "to take; to occupy; to claim", "note": ""}, {"ko": "데뷔하다", "en": "to debut; to make a first appearance", "note": ""}, {"ko": "기록하다", "en": "to record; to mark", "note": ""}, {"ko": "비연속", "en": "non-consecutive; discontinuous", "note": ""}, {"ko": "내려오다", "en": "to come down; to drop (in ranking)", "note": ""}, {"ko": "유지하다", "en": "to maintain; to keep", "note": ""}, {"ko": "올라오다", "en": "to come up; to rise (in ranking)", "note": ""}, {"ko": "상승하다", "en": "to rise; to go up", "note": ""}, {"ko": "높아지다", "en": "to become high; to improve (of ranking)", "note": ""}, {"ko": "꾸준히", "en": "steadily; consistently", "note": ""}, {"ko": "머물다", "en": "to stay; to remain", "note": ""}, {"ko": "뛰어오르다", "en": "to jump (up); to leap; to surge", "note": ""}]', grammar = '{"patterns": [{"name": "~면서", "level": "Intermediate", "exp": "Connective ending indicating concurrent or sequential actions. Shows that re-entering and achieving 1st place happen together.", "ex_ko": "이번 주 &TEAM의 미니 앨범 ''Mark on Me''가 차트 1위에 재진입하면서 그룹 역사상 처음으로 1위를 차지하게 되었습니다.", "ex_en": "&TEAM''s mini album ''Mark on Me'' re-entered the chart at number 1 this week, marking the first time the group has achieved number 1 status in their history."}, {"name": "~게 되다", "level": "Intermediate", "exp": "Auxiliary verb phrase expressing a change of state or realization. 차지하다 + 게 되다 indicates the group came to achieve 1st place (passive realization).", "ex_ko": "이번 주 &TEAM의 미니 앨범 ''Mark on Me''가 차트 1위에 재진입하면서 그룹 역사상 처음으로 1위를 차지하게 되었습니다.", "ex_en": "&TEAM''s mini album ''Mark on Me'' re-entered the chart at number 1 this week, marking the first time the group has achieved number 1 status in their history."}, {"name": "~(으)며", "level": "Intermediate", "exp": "Written connector ''and / while'': 데뷔하다 → 데뷔하며 ''debuted (in the top 20) and…''.", "ex_ko": "이 앨범은 빌보드 200에서도 상위 20위 안에 데뷔하며 &TEAM의 최고 순위를 기록했습니다.", "ex_en": "This album also debuted within the top 20 on the Billboard 200, recording &TEAM''s highest ranking."}, {"name": "~(으)ㄴ 후(에)", "level": "Intermediate", "exp": "''After doing'': 기록하다 → 기록한 후 ''after recording''.", "ex_ko": "스트레이 키즈의 최신 미니 앨범 ''THIS & THAT''은 여섯 번의 비연속 1위를 기록한 후 이번 주 2위로 내려왔습니다.", "ex_en": "Stray Kids'' latest mini album ''THIS & THAT'' has dropped to number 2 this week after recording six non-consecutive number 1s."}, {"name": "~(으)ㄴ 지 N째", "level": "Intermediate", "exp": "''It has been N since…'': 오르다 → 오른 지 8주째 ''the 8th week since it entered (the chart)''.", "ex_ko": "차트에 오른 지 8주째이며, 빌보드 200에서는 34위를 유지하고 있습니다.", "ex_en": "It is in its 8th week on the chart, and is maintaining 34th place on the Billboard 200."}, {"name": "~고 있다", "level": "Intermediate", "exp": "Progressive aspect marker. 머물다 + 고 있다 indicates the ongoing state of remaining on the chart.", "ex_ko": "차트에 오른 지 8주째이며, 빌보드 200에서는 34위를 유지하고 있습니다.", "ex_en": "It is in its 8th week on the chart, and is maintaining 34th place on the Billboard 200."}, {"name": "~(으)면서", "level": "Intermediate", "exp": "''While / as'': 올라오다 → 올라오면서 ''as it climbed back (to 161st)''.", "ex_ko": "빌보드 200에서도 161위로 다시 올라오면서 두 차트 모두에서 순위가 높아졌습니다.", "ex_en": "On the Billboard 200, it also rose again to 161st place, with rankings improving on both charts."}]}', updated_at = now() where article_id = 'mv4bo3fr1wel' and md5(translation) = '05c8800a110c012cf8e17407774decf2';
update public.article_cache set translation = '{"texts": ["A post asking how many refrigerators people have at home sparked wide interest on a Korean online community, with the original poster suggesting that having two or more seems to be the norm.", "In Korea, the kimchi refrigerator has long been established as an almost essential appliance alongside a regular fridge, since a separate unit is needed to store kimchi at the right temperature for extended periods.", "The cultural practice of preparing large quantities of food at once for occasions like holidays and ancestral rites is another reason many households need more than one refrigerator, with larger families or frequent cooks naturally requiring more cold storage space.", "Replies showed that many people consider two fridges the bare minimum, with quite a few mentioning three or more — a clear reflection of how Korean food culture shapes everyday home appliances."], "sentences": [{"text": "한 온라인 커뮤니티에 집에 냉장고가 몇 대 있는지 서로 이야기해 보자는 글이 올라오면서 많은 사람들의 관심을 끌게 되었습니다.", "translation": "When a post asking people to talk about how many refrigerators are in their homes was posted on an online community, it drew the attention of many people.", "vocab": [{"ko": "커뮤니티", "en": "community"}, {"ko": "올라오다", "en": "to be posted"}, {"ko": "관심을 끌다", "en": "to draw attention"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "''As / when'': 올라오다 → 올라오면서 ''as (the post) went up, …''.", "example_in_sentence": "올라오면서"}, {"type": "grammar", "label": "~게 되다", "exp": "Auxiliary construction expressing a change of state or result. Shows that attention-drawing occurred as an outcome.", "example_in_sentence": "관심을 끌게 되었습니다"}, {"type": "expression", "label": "관심을 끌다", "exp": "Common verb phrase meaning ''to attract/draw attention.'' The object marker ~을/를 is required.", "example_in_sentence": "많은 사람들의 관심을 끌게"}]}, {"text": "글쓴이는 두 대 이상인 경우가 대부분인 것 같다고 하면서 다른 사람들의 경험도 궁금해하였습니다.", "translation": "The author mentioned that most cases seemed to be two or more, while also expressing curiosity about others'' experiences.", "vocab": [{"ko": "글쓴이", "en": "author; post writer"}, {"ko": "대부분", "en": "majority; most"}, {"ko": "궁금해하다", "en": "to be curious about"}], "analysis": [{"type": "grammar", "label": "~인 것 같다", "exp": "''Seems to be'': 대부분이다 → 대부분인 것 같다 ''it seems to be the majority''.", "example_in_sentence": "대부분인 것 같다고"}, {"type": "grammar", "label": "~(으)면서", "exp": "''While (also)'': 하다 → 하면서 ''saying (that…) while also…''.", "example_in_sentence": "하면서"}]}, {"text": "한국에서는 김치냉장고가 일반 냉장고와 함께 거의 필수 가전제품으로 자리 잡은 지 오래입니다.", "translation": "In Korea, it has been a long time since kimchi refrigerators, along with regular refrigerators, became almost essential household appliances.", "vocab": [{"ko": "김치냉장고", "en": "kimchi refrigerator"}, {"ko": "필수 가전제품", "en": "essential home appliance"}, {"ko": "자리 잡다", "en": "to become established"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 지 오래다", "exp": "''It has been a long time since…'': 자리 잡다 → 자리 잡은 지 오래입니다.", "example_in_sentence": "자리 잡은 지 오래입니다"}, {"type": "expression", "label": "자리 잡다", "exp": "Idiomatic verb phrase meaning ''to become established or settled.'' Describes something gaining status or recognition.", "example_in_sentence": "거의 필수 가전제품으로 자리 잡은"}]}, {"text": "김치를 적절한 온도로 오래 보관하기 위해 별도의 냉장고가 필요하기 때문입니다.", "translation": "This is because a separate refrigerator is necessary to store kimchi at an appropriate temperature for a long time.", "vocab": [{"ko": "적절하다", "en": "to be appropriate; to be suitable"}, {"ko": "보관하다", "en": "to store; to keep"}, {"ko": "별도", "en": "separate; additional"}], "analysis": [{"type": "grammar", "label": "~기 위해", "exp": "''In order to'': 보관하다 → 보관하기 위해 ''in order to store''.", "example_in_sentence": "보관하기 위해"}, {"type": "grammar", "label": "~기 때문이다", "exp": "Reason/cause construction. The nominalized form ~기 + 때문 + copula explains why something is necessary.", "example_in_sentence": "필요하기 때문입니다"}]}, {"text": "그래서 많은 가정에서 냉장고를 두 대 이상 사용하는 것이 낯설지 않은 상황입니다.", "translation": "So in many homes, using two or more refrigerators is nothing unusual.", "vocab": [{"ko": "낯설다", "en": "to be unfamiliar; to be strange"}, {"ko": "상황", "en": "situation; circumstance"}], "analysis": [{"type": "grammar", "label": "~지 않다", "exp": "Negative ''not'': 낯설다 → 낯설지 않은 상황 ''a situation that is not unusual''.", "example_in_sentence": "낯설지 않은 상황"}]}, {"text": "또한 명절이나 제사처럼 음식을 한꺼번에 많이 준비하는 문화가 있는 것도 냉장고가 여러 대 필요한 이유 중 하나입니다.", "translation": "Also, the existence of a culture where food is prepared in large quantities all at once, like during holidays or ancestral rites, is one reason why multiple refrigerators are needed.", "vocab": [{"ko": "명절", "en": "holiday; festival"}, {"ko": "제사", "en": "ancestral rites"}, {"ko": "한꺼번에", "en": "all at once; in bulk"}, {"ko": "이유 중 하나", "en": "one of the reasons"}], "analysis": [{"type": "grammar", "label": "~처럼", "exp": "Particle meaning ''like; such as'': 명절이나 제사처럼 ''like holidays or ancestral rites''.", "example_in_sentence": "제사처럼"}, {"type": "grammar", "label": "~는 것도", "exp": "''The fact that … also'': 문화가 있다 → 문화가 있는 것도 ''the fact that there is a culture … is also (one reason)''.", "example_in_sentence": "있는 것도"}]}, {"text": "가족 수가 많거나 요리를 자주 하는 집일수록 냉장 공간이 더 필요하게 됩니다.", "translation": "The bigger the family, or the more often a household cooks, the more refrigerator space it needs.", "vocab": [{"ko": "가족 수", "en": "family size; number of family members"}, {"ko": "자주", "en": "frequently; often"}, {"ko": "냉장 공간", "en": "refrigeration space"}], "analysis": [{"type": "grammar", "label": "~거나", "exp": "''Or'': 많다 → 많거나 ''is large, or…''.", "example_in_sentence": "많거나"}, {"type": "grammar", "label": "~(으)ㄹ수록", "exp": "''The more …, the more''. After a noun it becomes 일수록: 요리를 자주 하는 집일수록 ''the more a home cooks often''.", "example_in_sentence": "집일수록"}, {"type": "grammar", "label": "~게 되다", "exp": "Auxiliary showing resultant state or change. Indicates that more space ''becomes'' necessary as a consequence.", "example_in_sentence": "필요하게 됩니다"}]}, {"text": "댓글에는 두 대는 기본이고 세 대 이상이라는 반응도 적지 않았습니다.", "translation": "In the comments, quite a few people said two was the norm and they had three or more.", "vocab": [{"ko": "댓글", "en": "comment"}, {"ko": "기본", "en": "basic; standard; default"}, {"ko": "반응", "en": "reaction; response"}], "analysis": [{"type": "grammar", "label": "~이고", "exp": "''Is N, and…'': 기본이다 → 기본이고 ''is the basic (number), and''.", "example_in_sentence": "기본이고"}, {"type": "grammar", "label": "~지 않다", "exp": "Negative form. ''적지 않다'' (lit. ''not few'') is a litotes idiom meaning ''considerable'' or ''not uncommon.''", "example_in_sentence": "적지 않았습니다"}]}, {"text": "한국 가정의 식문화가 냉장고 보유 대수에도 그대로 나타난다는 점이 흥미롭습니다.", "translation": "It is interesting that Korean households'' food culture is reflected as-is in the number of refrigerators they own.", "vocab": [{"ko": "식문화", "en": "food culture; culinary culture"}, {"ko": "보유", "en": "ownership; possession"}, {"ko": "대수", "en": "number of units"}, {"ko": "그대로", "en": "as-is; unchanged; exactly"}], "analysis": [{"type": "grammar", "label": "~ㄴ다는 점이", "exp": "Nominalization using ~ㄴ다는 + 점 (point/aspect). Converts a clause into a noun phrase emphasizing a particular aspect.", "example_in_sentence": "나타난다는 점이 흥미롭습니다"}, {"type": "expression", "label": "그대로 나타나다", "exp": "Common phrase meaning ''to be reflected/shown exactly as.'' Conveys how something manifests without change or distortion.", "example_in_sentence": "그대로 나타난다는"}]}], "version": "s6"}', vocab = '[{"ko": "커뮤니티", "en": "community", "note": ""}, {"ko": "올라오다", "en": "to be posted", "note": ""}, {"ko": "관심을 끌다", "en": "to draw attention", "note": ""}, {"ko": "글쓴이", "en": "author; post writer", "note": ""}, {"ko": "대부분", "en": "majority; most", "note": ""}, {"ko": "궁금해하다", "en": "to be curious about", "note": ""}, {"ko": "김치냉장고", "en": "kimchi refrigerator", "note": ""}, {"ko": "필수 가전제품", "en": "essential home appliance", "note": ""}, {"ko": "자리 잡다", "en": "to become established", "note": ""}, {"ko": "적절하다", "en": "to be appropriate; to be suitable", "note": ""}, {"ko": "보관하다", "en": "to store; to keep", "note": ""}, {"ko": "별도", "en": "separate; additional", "note": ""}, {"ko": "낯설다", "en": "to be unfamiliar; to be strange", "note": ""}, {"ko": "상황", "en": "situation; circumstance", "note": ""}, {"ko": "명절", "en": "holiday; festival", "note": ""}, {"ko": "제사", "en": "ancestral rites", "note": ""}, {"ko": "한꺼번에", "en": "all at once; in bulk", "note": ""}, {"ko": "이유 중 하나", "en": "one of the reasons", "note": ""}, {"ko": "가족 수", "en": "family size; number of family members", "note": ""}, {"ko": "자주", "en": "frequently; often", "note": ""}, {"ko": "냉장 공간", "en": "refrigeration space", "note": ""}, {"ko": "댓글", "en": "comment", "note": ""}, {"ko": "기본", "en": "basic; standard; default", "note": ""}, {"ko": "반응", "en": "reaction; response", "note": ""}, {"ko": "식문화", "en": "food culture; culinary culture", "note": ""}, {"ko": "보유", "en": "ownership; possession", "note": ""}, {"ko": "대수", "en": "number of units", "note": ""}, {"ko": "그대로", "en": "as-is; unchanged; exactly", "note": ""}]', grammar = '{"patterns": [{"name": "~(으)면서", "level": "Intermediate", "exp": "''While (also)'': 하다 → 하면서 ''saying (that…) while also…''.", "ex_ko": "한 온라인 커뮤니티에 집에 냉장고가 몇 대 있는지 서로 이야기해 보자는 글이 올라오면서 많은 사람들의 관심을 끌게 되었습니다.", "ex_en": "When a post asking people to talk about how many refrigerators are in their homes was posted on an online community, it drew the attention of many people."}, {"name": "~게 되다", "level": "Intermediate", "exp": "Auxiliary construction expressing a change of state or result. Shows that attention-drawing occurred as an outcome.", "ex_ko": "한 온라인 커뮤니티에 집에 냉장고가 몇 대 있는지 서로 이야기해 보자는 글이 올라오면서 많은 사람들의 관심을 끌게 되었습니다.", "ex_en": "When a post asking people to talk about how many refrigerators are in their homes was posted on an online community, it drew the attention of many people."}, {"name": "~인 것 같다", "level": "Intermediate", "exp": "''Seems to be'': 대부분이다 → 대부분인 것 같다 ''it seems to be the majority''.", "ex_ko": "글쓴이는 두 대 이상인 경우가 대부분인 것 같다고 하면서 다른 사람들의 경험도 궁금해하였습니다.", "ex_en": "The author mentioned that most cases seemed to be two or more, while also expressing curiosity about others'' experiences."}, {"name": "~(으)ㄴ 지 오래다", "level": "Intermediate", "exp": "''It has been a long time since…'': 자리 잡다 → 자리 잡은 지 오래입니다.", "ex_ko": "한국에서는 김치냉장고가 일반 냉장고와 함께 거의 필수 가전제품으로 자리 잡은 지 오래입니다.", "ex_en": "In Korea, it has been a long time since kimchi refrigerators, along with regular refrigerators, became almost essential household appliances."}, {"name": "~기 위해", "level": "Intermediate", "exp": "''In order to'': 보관하다 → 보관하기 위해 ''in order to store''.", "ex_ko": "김치를 적절한 온도로 오래 보관하기 위해 별도의 냉장고가 필요하기 때문입니다.", "ex_en": "This is because a separate refrigerator is necessary to store kimchi at an appropriate temperature for a long time."}, {"name": "~기 때문이다", "level": "Intermediate", "exp": "Reason/cause construction. The nominalized form ~기 + 때문 + copula explains why something is necessary.", "ex_ko": "김치를 적절한 온도로 오래 보관하기 위해 별도의 냉장고가 필요하기 때문입니다.", "ex_en": "This is because a separate refrigerator is necessary to store kimchi at an appropriate temperature for a long time."}, {"name": "~지 않다", "level": "Intermediate", "exp": "Negative form. ''적지 않다'' (lit. ''not few'') is a litotes idiom meaning ''considerable'' or ''not uncommon.''", "ex_ko": "그래서 많은 가정에서 냉장고를 두 대 이상 사용하는 것이 낯설지 않은 상황입니다.", "ex_en": "So in many homes, using two or more refrigerators is nothing unusual."}, {"name": "~처럼", "level": "Intermediate", "exp": "Particle meaning ''like; such as'': 명절이나 제사처럼 ''like holidays or ancestral rites''.", "ex_ko": "또한 명절이나 제사처럼 음식을 한꺼번에 많이 준비하는 문화가 있는 것도 냉장고가 여러 대 필요한 이유 중 하나입니다.", "ex_en": "Also, the existence of a culture where food is prepared in large quantities all at once, like during holidays or ancestral rites, is one reason why multiple refrigerators are needed."}, {"name": "~는 것도", "level": "Intermediate", "exp": "''The fact that … also'': 문화가 있다 → 문화가 있는 것도 ''the fact that there is a culture … is also (one reason)''.", "ex_ko": "또한 명절이나 제사처럼 음식을 한꺼번에 많이 준비하는 문화가 있는 것도 냉장고가 여러 대 필요한 이유 중 하나입니다.", "ex_en": "Also, the existence of a culture where food is prepared in large quantities all at once, like during holidays or ancestral rites, is one reason why multiple refrigerators are needed."}, {"name": "~거나", "level": "Intermediate", "exp": "''Or'': 많다 → 많거나 ''is large, or…''.", "ex_ko": "가족 수가 많거나 요리를 자주 하는 집일수록 냉장 공간이 더 필요하게 됩니다.", "ex_en": "The bigger the family, or the more often a household cooks, the more refrigerator space it needs."}, {"name": "~(으)ㄹ수록", "level": "Intermediate", "exp": "''The more …, the more''. After a noun it becomes 일수록: 요리를 자주 하는 집일수록 ''the more a home cooks often''.", "ex_ko": "가족 수가 많거나 요리를 자주 하는 집일수록 냉장 공간이 더 필요하게 됩니다.", "ex_en": "The bigger the family, or the more often a household cooks, the more refrigerator space it needs."}, {"name": "~이고", "level": "Intermediate", "exp": "''Is N, and…'': 기본이다 → 기본이고 ''is the basic (number), and''.", "ex_ko": "댓글에는 두 대는 기본이고 세 대 이상이라는 반응도 적지 않았습니다.", "ex_en": "In the comments, quite a few people said two was the norm and they had three or more."}, {"name": "~ㄴ다는 점이", "level": "Intermediate", "exp": "Nominalization using ~ㄴ다는 + 점 (point/aspect). Converts a clause into a noun phrase emphasizing a particular aspect.", "ex_ko": "한국 가정의 식문화가 냉장고 보유 대수에도 그대로 나타난다는 점이 흥미롭습니다.", "ex_en": "It is interesting that Korean households'' food culture is reflected as-is in the number of refrigerators they own."}]}', updated_at = now() where article_id = 'mv4cdxsd9kfn' and md5(translation) = '8fd519a41d91839e982abdd95937d58a';
update public.article_cache set translation = '{"texts": ["Samantha Rensvold was adopted as a baby and had always known she had a biological sister somewhere.", "On August 1, 2025, Samantha was playing softball in Montana when she noticed a player on the opposing team named Kyann Dean.", "A teammate told Samantha that the opposing player looked exactly like her, and Samantha was stunned when she saw her.", "Samantha told her adoptive mother, who spotted the name ''Kyann'' on the roster and recognized it as the name given by the birth mother.", "The two mothers spoke and confirmed that the girls shared the same birth mother and were born at the same hospital — the two were biological sisters.", "Later, Samantha also learned she had a biological brother, who had already tracked her down years earlier.", "Both girls had played volleyball in high school, in the same position and wearing the same number; they are now attending college in separate states."], "sentences": [{"text": "사만사 렌스볼드는 아기 때 입양됐어요.", "translation": "Samantha Lensworld was adopted when she was a baby.", "vocab": [{"ko": "아기", "en": "baby"}, {"ko": "입양되다", "en": "to be adopted"}], "analysis": [{"type": "grammar", "label": "N 때", "exp": "''When (someone was) N'': 아기 + 때 = ''when she was a baby''.", "example_in_sentence": "아기 때"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending for declarative statements. Combines past marker ~았/었 with polite formal ~어요. 입양되 (be adopted) + 었 (past) + 어요 (polite).", "example_in_sentence": "입양됐어요"}]}, {"text": "그녀는 어딘가에 친언니가 있다는 것을 알고 있었어요.", "translation": "She knew that she had a biological older sister somewhere.", "vocab": [{"ko": "어딘가", "en": "somewhere"}, {"ko": "친언니", "en": "biological older sister"}, {"ko": "알다", "en": "to know"}], "analysis": [{"type": "grammar", "label": "~다는 것을", "exp": "Nominalization pattern converting clauses into objects of knowledge/recognition. 있다 (exist) + ~다는 것 (the fact that) + 을 (object marker) creates ''the fact that there is''.", "example_in_sentence": "있다는 것을"}, {"type": "grammar", "label": "~고 있다 (state)", "exp": "알고 있다 means ''to know'' (a state). 알다 → 알고 있었어요 ''knew''.", "example_in_sentence": "알고 있었어요"}]}, {"text": "2025년 8월 1일, 사만사는 몬태나에서 소프트볼 경기를 했어요.", "translation": "On August 1, 2025, Samantha played a softball game in Montana.", "vocab": [{"ko": "몬태나", "en": "Montana"}, {"ko": "소프트볼", "en": "softball"}, {"ko": "경기", "en": "game; match"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locational particle marking the place where an action occurs. 몬태나 (Montana) + 에서 (in/at) indicates ''in Montana''.", "example_in_sentence": "몬태나에서"}, {"type": "grammar", "label": "~를/을 하다", "exp": "Light verb construction where 하다 (do) governs an object. 경기 (game) + 를 (object) + 하 (do) = ''play a game''.", "example_in_sentence": "경기를 했어요"}]}, {"text": "상대 팀에 키안 딘이라는 선수가 있었어요.", "translation": "There was a player named Kian Dean on the opposing team.", "vocab": [{"ko": "상대", "en": "opponent; opposing"}, {"ko": "선수", "en": "player; athlete"}], "analysis": [{"type": "grammar", "label": "~이라는", "exp": "Attributive clause particle marking a name or title. 키안 딘 (Kian Dean) + 이라는 (called/named) + 선수 (player) = ''a player named Kian Dean''.", "example_in_sentence": "키안 딘이라는 선수"}, {"type": "grammar", "label": "N에 N이/가 있다", "exp": "''There is N in/on N'': 팀에 … 선수가 있었어요 ''there was a player on the team''.", "example_in_sentence": "선수가 있었어요"}]}, {"text": "친구가 사만사에게 말했어요.", "translation": "A friend told Samantha.", "vocab": [{"ko": "친구", "en": "friend"}, {"ko": "말하다", "en": "to tell; to speak"}], "analysis": [{"type": "grammar", "label": "~에게", "exp": "Indirect object particle for animate beings marking recipient of action. 사만사 (Samantha) + 에게 (to) = ''to Samantha''.", "example_in_sentence": "사만사에게"}]}, {"text": "상대 팀 선수가 사만사랑 똑같이 생겼다고 했어요.", "translation": "The friend said a player on the other team looked exactly like Samantha.", "vocab": [{"ko": "똑같이", "en": "exactly the same; identically"}, {"ko": "생기다", "en": "to look; to appear"}], "analysis": [{"type": "grammar", "label": "~랑", "exp": "Colloquial comitative/comparative particle (variant of ~과/와). 사만사 (Samantha) + 랑 (with/like) = ''like Samantha'' or ''same as Samantha''.", "example_in_sentence": "사만사랑"}, {"type": "grammar", "label": "~다고 하다", "exp": "Reported speech pattern. 생겼다 (looked) + 고 (quotative) + 하 (do/say) = ''said that [someone] looked''.", "example_in_sentence": "생겼다고 했어요"}]}, {"text": "사만사는 그 선수를 보고 깜짝 놀랐어요.", "translation": "Samantha was startled when she saw the player.", "vocab": [{"ko": "깜짝", "en": "with a start; suddenly"}, {"ko": "놀라다", "en": "to be surprised; to be startled"}], "analysis": [{"type": "grammar", "label": "~고", "exp": "Connective ending joining two actions sequentially. 보 (see) + 고 (and then) + 놀랐어요 (was startled) = ''saw and then was startled''.", "example_in_sentence": "보고"}]}, {"text": "사만사는 엄마에게 이야기했어요.", "translation": "Samantha told her mother.", "vocab": [{"ko": "엄마", "en": "mother"}, {"ko": "이야기하다", "en": "to tell; to talk"}], "analysis": []}, {"text": "엄마는 상대 팀 명단에서 ''키안''이라는 이름을 봤어요.", "translation": "Her mom saw the name ''Kian'' on the opposing team''s roster.", "vocab": [{"ko": "명단", "en": "roster; list; lineup"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locational particle for place where an action occurs. 명단 (roster) + 에서 (in/from) = ''in the roster''.", "example_in_sentence": "명단에서"}]}, {"text": "엄마는 그 이름이 친엄마가 지은 이름이라는 걸 알고 있었어요.", "translation": "Her mom knew that the name had been given by the birth mother.", "vocab": [{"ko": "친엄마", "en": "biological mother"}, {"ko": "짓다", "en": "to give (a name); to make"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "짓다 ''to give (a name)'' is ㅅ-irregular: 짓다 → 지은 이름 ''a name (she) gave''.", "example_in_sentence": "지은 이름"}, {"type": "grammar", "label": "~(이)라는 걸", "exp": "''That it is …'' as an object: 이름이다 → 이름이라는 걸 (걸 = 것을).", "example_in_sentence": "이름이라는 걸"}]}, {"text": "두 엄마가 이야기를 나눴어요.", "translation": "The two mothers talked with each other.", "vocab": [{"ko": "두", "en": "two"}, {"ko": "나누다", "en": "to share; to exchange"}], "analysis": [{"type": "grammar", "label": "이야기를 나누다", "exp": "''To have a conversation'': 이야기를 나누다 → 이야기를 나눴어요 ''talked''.", "example_in_sentence": "이야기를 나눴어요"}]}, {"text": "두 아이의 친엄마 이름과 태어난 병원이 같았어요.", "translation": "The two children had the same birth mother''s name and were born in the same hospital.", "vocab": [{"ko": "태어나다", "en": "to be born"}, {"ko": "병원", "en": "hospital"}, {"ko": "같다", "en": "to be the same"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier: 태어나다 → 태어난 병원 ''the hospital where (they) were born''.", "example_in_sentence": "태어난 병원"}, {"type": "grammar", "label": "~와/과 (and)", "exp": "Joins two nouns, ''and'': 이름과 병원 ''the name and the hospital''. 과 follows a consonant.", "example_in_sentence": "이름과"}]}, {"text": "사만사와 키안은 친자매였어요.", "translation": "Samantha and Kian were biological sisters.", "vocab": [{"ko": "친자매", "en": "biological sisters"}], "analysis": [{"type": "grammar", "label": "~와/과 (and)", "exp": "''And'' between nouns: 사만사와 키안 ''Samantha and Kian''. 와 after a vowel, 과 after a consonant; 랑 is the casual form.", "example_in_sentence": "사만사와"}]}, {"text": "나중에 사만사는 친오빠도 있다는 것을 알았어요.", "translation": "Later, Samantha found out she also had a biological older brother.", "vocab": [{"ko": "나중에", "en": "later"}, {"ko": "친오빠", "en": "biological older brother"}], "analysis": [{"type": "grammar", "label": "~도", "exp": "Additive particle meaning ''also/even''. 친오빠 (biological brother) + 도 (also) = ''also had a brother''.", "example_in_sentence": "친오빠도"}, {"type": "grammar", "label": "~다는 것을", "exp": "Nominalization creating object of 알다 (know/find out). 있다 (have/exist) + ~다는 것 (the fact that) + 을 (object) = ''the fact that there was/had''.", "example_in_sentence": "있다는 것을"}]}, {"text": "친오빠는 몇 년 전에 먼저 사만사를 찾아왔어요.", "translation": "Her biological older brother had come looking for Samantha a few years ago.", "vocab": [{"ko": "몇", "en": "how many; some"}, {"ko": "년", "en": "year"}, {"ko": "먼저", "en": "first; ahead"}], "analysis": [{"type": "grammar", "label": "N 전에", "exp": "''N ago'': 몇 년 전에 ''a few years ago''.", "example_in_sentence": "몇 년 전에"}, {"type": "expression", "label": "찾아오다", "exp": "Compound verb (찾다 + 오다) meaning ''to come seeking/looking for''. Directional ~아/어 오다 indicates motion toward the speaker.", "example_in_sentence": "찾아왔어요"}]}, {"text": "두 사람은 고등학교에서 둘 다 배구를 했어요.", "translation": "Both of them played volleyball in high school.", "vocab": [{"ko": "고등학교", "en": "high school"}, {"ko": "배구", "en": "volleyball"}], "analysis": [{"type": "grammar", "label": "둘 다", "exp": "''Both'': 둘 ''two'' + 다 ''all'' = ''both of them''.", "example_in_sentence": "둘 다"}]}, {"text": "같은 자리에서, 같은 번호를 달고 뛰었어요.", "translation": "They played in the same position, wearing the same number.", "vocab": [{"ko": "자리", "en": "position; place; seat"}, {"ko": "번호", "en": "number"}, {"ko": "달다", "en": "to wear; to attach"}], "analysis": [{"type": "grammar", "label": "~고", "exp": "Connective ending joining two parallel actions. 달 (wear) + 고 (and) + 뛰다 (play/run) = ''wore and played''.", "example_in_sentence": "달고 뛰었어요"}]}, {"text": "지금은 각각 다른 주에서 대학을 다니고 있어요.", "translation": "Now they each attend university in different states.", "vocab": [{"ko": "각각", "en": "each; respectively"}, {"ko": "다르다", "en": "to be different"}, {"ko": "주", "en": "state"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a noun modifier: 다르다 → 다른 주 ''different states''.", "example_in_sentence": "다른 주"}, {"type": "grammar", "label": "~고 있어요", "exp": "Continuous present tense. 다니 (attend) + 고 있 (be in state of) + 어요 (polite) = ''are attending (ongoing state)''.", "example_in_sentence": "다니고 있어요"}]}], "version": "s6"}', vocab = '[{"ko": "아기", "en": "baby", "note": ""}, {"ko": "입양되다", "en": "to be adopted", "note": ""}, {"ko": "어딘가", "en": "somewhere", "note": ""}, {"ko": "친언니", "en": "biological older sister", "note": ""}, {"ko": "알다", "en": "to know", "note": ""}, {"ko": "몬태나", "en": "Montana", "note": ""}, {"ko": "소프트볼", "en": "softball", "note": ""}, {"ko": "경기", "en": "game; match", "note": ""}, {"ko": "상대", "en": "opponent; opposing", "note": ""}, {"ko": "선수", "en": "player; athlete", "note": ""}, {"ko": "친구", "en": "friend", "note": ""}, {"ko": "말하다", "en": "to tell; to speak", "note": ""}, {"ko": "똑같이", "en": "exactly the same; identically", "note": ""}, {"ko": "생기다", "en": "to look; to appear", "note": ""}, {"ko": "깜짝", "en": "with a start; suddenly", "note": ""}, {"ko": "놀라다", "en": "to be surprised; to be startled", "note": ""}, {"ko": "엄마", "en": "mother", "note": ""}, {"ko": "이야기하다", "en": "to tell; to talk", "note": ""}, {"ko": "명단", "en": "roster; list; lineup", "note": ""}, {"ko": "친엄마", "en": "biological mother", "note": ""}, {"ko": "짓다", "en": "to give (a name); to make", "note": ""}, {"ko": "두", "en": "two", "note": ""}, {"ko": "나누다", "en": "to share; to exchange", "note": ""}, {"ko": "태어나다", "en": "to be born", "note": ""}, {"ko": "병원", "en": "hospital", "note": ""}, {"ko": "같다", "en": "to be the same", "note": ""}, {"ko": "친자매", "en": "biological sisters", "note": ""}, {"ko": "나중에", "en": "later", "note": ""}, {"ko": "친오빠", "en": "biological older brother", "note": ""}, {"ko": "몇", "en": "how many; some", "note": ""}, {"ko": "년", "en": "year", "note": ""}, {"ko": "먼저", "en": "first; ahead", "note": ""}, {"ko": "고등학교", "en": "high school", "note": ""}, {"ko": "배구", "en": "volleyball", "note": ""}, {"ko": "자리", "en": "position; place; seat", "note": ""}, {"ko": "번호", "en": "number", "note": ""}, {"ko": "달다", "en": "to wear; to attach", "note": ""}, {"ko": "각각", "en": "each; respectively", "note": ""}, {"ko": "다르다", "en": "to be different", "note": ""}, {"ko": "주", "en": "state", "note": ""}]', grammar = '{"patterns": [{"name": "N 때", "level": "Starter", "exp": "''When (someone was) N'': 아기 + 때 = ''when she was a baby''.", "ex_ko": "사만사 렌스볼드는 아기 때 입양됐어요.", "ex_en": "Samantha Lensworld was adopted when she was a baby."}, {"name": "~았/었어요", "level": "Starter", "exp": "Past tense ending for declarative statements. Combines past marker ~았/었 with polite formal ~어요. 입양되 (be adopted) + 었 (past) + 어요 (polite).", "ex_ko": "사만사 렌스볼드는 아기 때 입양됐어요.", "ex_en": "Samantha Lensworld was adopted when she was a baby."}, {"name": "~다는 것을", "level": "Starter", "exp": "Nominalization pattern converting clauses into objects of knowledge/recognition. 있다 (exist) + ~다는 것 (the fact that) + 을 (object marker) creates ''the fact that there is''.", "ex_ko": "그녀는 어딘가에 친언니가 있다는 것을 알고 있었어요.", "ex_en": "She knew that she had a biological older sister somewhere."}, {"name": "~고 있다 (state)", "level": "Starter", "exp": "알고 있다 means ''to know'' (a state). 알다 → 알고 있었어요 ''knew''.", "ex_ko": "그녀는 어딘가에 친언니가 있다는 것을 알고 있었어요.", "ex_en": "She knew that she had a biological older sister somewhere."}, {"name": "~에서", "level": "Starter", "exp": "Locational particle marking the place where an action occurs. 몬태나 (Montana) + 에서 (in/at) indicates ''in Montana''.", "ex_ko": "2025년 8월 1일, 사만사는 몬태나에서 소프트볼 경기를 했어요.", "ex_en": "On August 1, 2025, Samantha played a softball game in Montana."}, {"name": "~를/을 하다", "level": "Starter", "exp": "Light verb construction where 하다 (do) governs an object. 경기 (game) + 를 (object) + 하 (do) = ''play a game''.", "ex_ko": "2025년 8월 1일, 사만사는 몬태나에서 소프트볼 경기를 했어요.", "ex_en": "On August 1, 2025, Samantha played a softball game in Montana."}, {"name": "~이라는", "level": "Starter", "exp": "Attributive clause particle marking a name or title. 키안 딘 (Kian Dean) + 이라는 (called/named) + 선수 (player) = ''a player named Kian Dean''.", "ex_ko": "상대 팀에 키안 딘이라는 선수가 있었어요.", "ex_en": "There was a player named Kian Dean on the opposing team."}, {"name": "N에 N이/가 있다", "level": "Starter", "exp": "''There is N in/on N'': 팀에 … 선수가 있었어요 ''there was a player on the team''.", "ex_ko": "상대 팀에 키안 딘이라는 선수가 있었어요.", "ex_en": "There was a player named Kian Dean on the opposing team."}, {"name": "~에게", "level": "Starter", "exp": "Indirect object particle for animate beings marking recipient of action. 사만사 (Samantha) + 에게 (to) = ''to Samantha''.", "ex_ko": "친구가 사만사에게 말했어요.", "ex_en": "A friend told Samantha."}, {"name": "~랑", "level": "Starter", "exp": "Colloquial comitative/comparative particle (variant of ~과/와). 사만사 (Samantha) + 랑 (with/like) = ''like Samantha'' or ''same as Samantha''.", "ex_ko": "상대 팀 선수가 사만사랑 똑같이 생겼다고 했어요.", "ex_en": "The friend said a player on the other team looked exactly like Samantha."}, {"name": "~다고 하다", "level": "Starter", "exp": "Reported speech pattern. 생겼다 (looked) + 고 (quotative) + 하 (do/say) = ''said that [someone] looked''.", "ex_ko": "상대 팀 선수가 사만사랑 똑같이 생겼다고 했어요.", "ex_en": "The friend said a player on the other team looked exactly like Samantha."}, {"name": "~고", "level": "Starter", "exp": "Connective ending joining two actions sequentially. 보 (see) + 고 (and then) + 놀랐어요 (was startled) = ''saw and then was startled''.", "ex_ko": "사만사는 그 선수를 보고 깜짝 놀랐어요.", "ex_en": "Samantha was startled when she saw the player."}, {"name": "~(으)ㄴ (adjective modifier)", "level": "Starter", "exp": "Turns an adjective into a noun modifier: 다르다 → 다른 주 ''different states''.", "ex_ko": "엄마는 그 이름이 친엄마가 지은 이름이라는 걸 알고 있었어요.", "ex_en": "Her mom knew that the name had been given by the birth mother."}, {"name": "~(이)라는 걸", "level": "Starter", "exp": "''That it is …'' as an object: 이름이다 → 이름이라는 걸 (걸 = 것을).", "ex_ko": "엄마는 그 이름이 친엄마가 지은 이름이라는 걸 알고 있었어요.", "ex_en": "Her mom knew that the name had been given by the birth mother."}, {"name": "이야기를 나누다", "level": "Starter", "exp": "''To have a conversation'': 이야기를 나누다 → 이야기를 나눴어요 ''talked''.", "ex_ko": "두 엄마가 이야기를 나눴어요.", "ex_en": "The two mothers talked with each other."}]}', updated_at = now() where article_id = 'mv5qr0i0uxsu' and md5(translation) = '580187f6756ffb207e6d657431aee254';
update public.article_cache set translation = '{"texts": ["The comedy film ''Ugly Duckling Ms. Maeng'' is opening soon. The main character, Maeng Bo Ram, is a Korean language teacher from a small town.", "Maeng Bo Ram accidentally joins the team responsible for creating Korea''s CSAT (Suneung) questions. The question-setting headquarters is sealed off for 40 days, and the team works in complete secrecy.", "The film features a variety of characters, including Korean literature professor Na Eun Mi, aesthetics professor Ye, and veteran question writer Kang Ji Hye, who has served on the committee five times. CSAT review committee head Park Kyung Tae and Korean language committee head Moon Joo Yeol also appear.", "Lee Sun Bin plays the role of Maeng Bo Ram. Yoo Jae Myung, Hwang Bo Ra, Jung Soo Young, Lee Jin Hee, Kim Young Min, Kim Kyung Min, Lee Joong Ok, and Jeon Seok Ho also star in the film. It opens in theaters nationwide on October 28."], "sentences": [{"text": "영화 ''추한 오리 맹 여사''가 곧 개봉해요.", "translation": "The movie ''Ugly Duckling Ms. Maeng'' is opening soon.", "vocab": [{"ko": "영화", "en": "movie"}, {"ko": "곧", "en": "soon"}, {"ko": "개봉하다", "en": "to open (of a film)"}], "analysis": [{"type": "grammar", "label": "~아/어요", "exp": "Present polite ending; with 곧 ''soon'' it describes a near-future plan. 하다 verbs become 해요: 개봉하다 → 개봉해요.", "example_in_sentence": "개봉해요"}]}, {"text": "이 영화는 코미디 영화예요.", "translation": "This movie is a comedy film.", "vocab": [{"ko": "이", "en": "this"}, {"ko": "코미디", "en": "comedy"}], "analysis": [{"type": "grammar", "label": "~예요/이에요", "exp": "Copula (to be) in polite declarative form. Used after nouns to state identity or classification.", "example_in_sentence": "영화예요"}]}, {"text": "주인공 맹보람은 작은 도시의 국어 선생님이에요.", "translation": "The protagonist Maeng Boram is a Korean language teacher in a small city.", "vocab": [{"ko": "주인공", "en": "protagonist"}, {"ko": "작다", "en": "to be small"}, {"ko": "국어", "en": "Korean language"}, {"ko": "선생님", "en": "teacher"}], "analysis": [{"type": "grammar", "label": "의 (genitive particle)", "exp": "Possessive/genitive particle marking relationship between nouns. Links ''도시'' (city) to ''국어 선생님'' (teacher).", "example_in_sentence": "도시의 국어"}, {"type": "grammar", "label": "~이에요", "exp": "Copula in polite declarative form. Used after noun stems ending in consonants.", "example_in_sentence": "선생님이에요"}]}, {"text": "맹보람은 실수로 수능 문제를 만드는 팀에 들어가요.", "translation": "Maeng Boram accidentally joins a team that creates college entrance exam questions.", "vocab": [{"ko": "실수", "en": "mistake"}, {"ko": "수능", "en": "College Entrance Exam (수학능력시험)"}, {"ko": "만들다", "en": "to make"}, {"ko": "팀", "en": "team"}], "analysis": [{"type": "grammar", "label": "로 (instrumental particle)", "exp": "Marks manner or means of action. Shows how the action occurs.", "example_in_sentence": "실수로"}, {"type": "grammar", "label": "~는 (present participle/relative clause marker)", "exp": "Modifies noun by forming relative clause. 만들다 → 만드는 (that makes/creating).", "example_in_sentence": "만드는 팀"}, {"type": "grammar", "label": "에 (locative particle)", "exp": "Marks destination or location. Shows movement into or joining a group.", "example_in_sentence": "팀에 들어가요"}]}, {"text": "수능 문제를 만드는 곳은 40일 동안 완전히 닫혀 있어요.", "translation": "The place where college entrance exam questions are created is completely closed for 40 days.", "vocab": [{"ko": "곳", "en": "place"}, {"ko": "동안", "en": "during; for (a period)"}, {"ko": "완전히", "en": "completely"}, {"ko": "닫히다", "en": "to be closed"}], "analysis": [{"type": "expression", "label": "~동안", "exp": "Duration marker following noun. Indicates period during which an action occurs or state is maintained.", "example_in_sentence": "40일 동안"}, {"type": "grammar", "label": "~아/어 있다", "exp": "Shows a state that continues: 닫히다 ''to be closed'' → 닫혀 있어요 ''stays closed''.", "example_in_sentence": "닫혀 있어요"}]}, {"text": "팀원들은 비밀리에 일해요.", "translation": "Team members work secretly.", "vocab": [{"ko": "팀원", "en": "team member"}, {"ko": "비밀리에", "en": "in secret; secretly"}, {"ko": "일하다", "en": "to work"}], "analysis": [{"type": "grammar", "label": "~아/어요", "exp": "Present tense polite declarative ending for action verbs.", "example_in_sentence": "일해요"}]}, {"text": "이 영화에는 여러 캐릭터가 나와요.", "translation": "This movie features several characters.", "vocab": [{"ko": "여러", "en": "several; many"}, {"ko": "캐릭터", "en": "character"}, {"ko": "나오다", "en": "to appear; to come out"}], "analysis": [{"type": "grammar", "label": "에는 (locative + topic particle)", "exp": "Combines 에 (in) and 는 (topic). Marks location with emphasis/contrast.", "example_in_sentence": "영화에는"}, {"type": "grammar", "label": "~아/어요", "exp": "Present tense polite declarative ending.", "example_in_sentence": "나와요"}]}, {"text": "한국 문학 교수 나은미, 미학 교수 예 교수, 수능 출제 경험이 많은 강지혜가 나와요.", "translation": "Korean literature professor Na Eun-mi, aesthetics professor Professor Ye, and Kang Ji-hye, who has a lot of experience writing CSAT questions, appear.", "vocab": [{"ko": "한국 문학", "en": "Korean literature"}, {"ko": "교수", "en": "professor"}, {"ko": "미학", "en": "aesthetics"}, {"ko": "경험", "en": "experience"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a noun modifier: 많다 → 경험이 많은 강지혜 ''Kang Ji-hye, who has a lot of experience''.", "example_in_sentence": "많은 강지혜"}]}, {"text": "또 수능 검토 위원장 박경태와 국어 출제 위원장 문주열도 나와요.", "translation": "Park Kyung-tae, head of the CSAT review committee, and Moon Ju-yeol, head of the Korean-language question committee, also appear.", "vocab": [{"ko": "또", "en": "also; moreover"}, {"ko": "검토", "en": "review; examination"}, {"ko": "위원장", "en": "director; chairperson"}, {"ko": "출제", "en": "test creation"}], "analysis": [{"type": "grammar", "label": "와/과 (conjunctive particle)", "exp": "Connects two nouns in coordination. Marks ''and'' relationship between items.", "example_in_sentence": "박경태와"}, {"type": "grammar", "label": "도 (inclusive particle)", "exp": "Adds inclusive meaning (''also'', ''as well''). Applied to the second subject in a list.", "example_in_sentence": "문주열도"}]}, {"text": "맹보람 역은 이선빈이 맡았어요.", "translation": "The role of Maeng Boram was taken by Lee Sunbin.", "vocab": [{"ko": "역", "en": "role"}, {"ko": "맡다", "en": "to take (a role); to undertake"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite declarative ending. Marks completed action. 맡다 → 맡았어요.", "example_in_sentence": "맡았어요"}]}, {"text": "유재명, 황보라, 정수영, 이진희, 김영민, 김경민, 이중옥, 전석호도 출연해요.", "translation": "Yu Jaemyeong, Hwang Bora, Jung Suyoung, Lee Jinhee, Kim Youngmin, Kim Kyungmin, Lee Jungouk, and Jeon Seokho also appear.", "vocab": [{"ko": "출연하다", "en": "to appear (in a film); to perform"}], "analysis": [{"type": "grammar", "label": "도 (inclusive particle)", "exp": "Adds inclusive meaning applied to the last item in a list. Shows these actors also appear like previously mentioned ones.", "example_in_sentence": "전석호도"}, {"type": "grammar", "label": "~아/어요", "exp": "Present tense polite declarative ending.", "example_in_sentence": "출연해요"}]}, {"text": "영화는 10월 28일에 전국 극장에서 볼 수 있어요.", "translation": "The movie can be seen in theaters nationwide on October 28th.", "vocab": [{"ko": "월", "en": "month"}, {"ko": "일", "en": "day (in dates)"}, {"ko": "전국", "en": "nationwide; whole country"}, {"ko": "극장", "en": "theater"}], "analysis": [{"type": "grammar", "label": "에서 (locative particle)", "exp": "Marks location where action occurs. Shows where the movie can be watched.", "example_in_sentence": "극장에서"}, {"type": "grammar", "label": "~ㄹ 수 있어요", "exp": "Expresses possibility or ability. 보다 → 볼 수 있다 (can watch/see).", "example_in_sentence": "볼 수 있어요"}]}], "version": "s6"}', vocab = '[{"ko": "영화", "en": "movie", "note": ""}, {"ko": "곧", "en": "soon", "note": ""}, {"ko": "개봉하다", "en": "to open (of a film)", "note": ""}, {"ko": "이", "en": "this", "note": ""}, {"ko": "코미디", "en": "comedy", "note": ""}, {"ko": "주인공", "en": "protagonist", "note": ""}, {"ko": "작다", "en": "to be small", "note": ""}, {"ko": "국어", "en": "Korean language", "note": ""}, {"ko": "선생님", "en": "teacher", "note": ""}, {"ko": "실수", "en": "mistake", "note": ""}, {"ko": "수능", "en": "College Entrance Exam (수학능력시험)", "note": ""}, {"ko": "만들다", "en": "to make", "note": ""}, {"ko": "팀", "en": "team", "note": ""}, {"ko": "곳", "en": "place", "note": ""}, {"ko": "동안", "en": "during; for (a period)", "note": ""}, {"ko": "완전히", "en": "completely", "note": ""}, {"ko": "닫히다", "en": "to be closed", "note": ""}, {"ko": "팀원", "en": "team member", "note": ""}, {"ko": "비밀리에", "en": "in secret; secretly", "note": ""}, {"ko": "일하다", "en": "to work", "note": ""}, {"ko": "여러", "en": "several; many", "note": ""}, {"ko": "캐릭터", "en": "character", "note": ""}, {"ko": "나오다", "en": "to appear; to come out", "note": ""}, {"ko": "한국 문학", "en": "Korean literature", "note": ""}, {"ko": "교수", "en": "professor", "note": ""}, {"ko": "미학", "en": "aesthetics", "note": ""}, {"ko": "경험", "en": "experience", "note": ""}, {"ko": "또", "en": "also; moreover", "note": ""}, {"ko": "검토", "en": "review; examination", "note": ""}, {"ko": "위원장", "en": "director; chairperson", "note": ""}, {"ko": "출제", "en": "test creation", "note": ""}, {"ko": "역", "en": "role", "note": ""}, {"ko": "맡다", "en": "to take (a role); to undertake", "note": ""}, {"ko": "출연하다", "en": "to appear (in a film); to perform", "note": ""}, {"ko": "월", "en": "month", "note": ""}, {"ko": "일", "en": "day (in dates)", "note": ""}, {"ko": "전국", "en": "nationwide; whole country", "note": ""}, {"ko": "극장", "en": "theater", "note": ""}]', grammar = '{"patterns": [{"name": "~아/어요", "level": "Beginner", "exp": "Present polite ending; with 곧 ''soon'' it describes a near-future plan. 하다 verbs become 해요: 개봉하다 → 개봉해요.", "ex_ko": "영화 ''추한 오리 맹 여사''가 곧 개봉해요.", "ex_en": "The movie ''Ugly Duckling Ms. Maeng'' is opening soon."}, {"name": "~예요/이에요", "level": "Beginner", "exp": "Copula (to be) in polite declarative form. Used after nouns to state identity or classification.", "ex_ko": "이 영화는 코미디 영화예요.", "ex_en": "This movie is a comedy film."}, {"name": "의 (genitive particle)", "level": "Beginner", "exp": "Possessive/genitive particle marking relationship between nouns. Links ''도시'' (city) to ''국어 선생님'' (teacher).", "ex_ko": "주인공 맹보람은 작은 도시의 국어 선생님이에요.", "ex_en": "The protagonist Maeng Boram is a Korean language teacher in a small city."}, {"name": "~이에요", "level": "Beginner", "exp": "Copula in polite declarative form. Used after noun stems ending in consonants.", "ex_ko": "주인공 맹보람은 작은 도시의 국어 선생님이에요.", "ex_en": "The protagonist Maeng Boram is a Korean language teacher in a small city."}, {"name": "로 (instrumental particle)", "level": "Beginner", "exp": "Marks manner or means of action. Shows how the action occurs.", "ex_ko": "맹보람은 실수로 수능 문제를 만드는 팀에 들어가요.", "ex_en": "Maeng Boram accidentally joins a team that creates college entrance exam questions."}, {"name": "~는 (present participle/relative clause marker)", "level": "Beginner", "exp": "Modifies noun by forming relative clause. 만들다 → 만드는 (that makes/creating).", "ex_ko": "맹보람은 실수로 수능 문제를 만드는 팀에 들어가요.", "ex_en": "Maeng Boram accidentally joins a team that creates college entrance exam questions."}, {"name": "에서 (locative particle)", "level": "Beginner", "exp": "Marks location where action occurs. Shows where the movie can be watched.", "ex_ko": "맹보람은 실수로 수능 문제를 만드는 팀에 들어가요.", "ex_en": "Maeng Boram accidentally joins a team that creates college entrance exam questions."}, {"name": "~아/어 있다", "level": "Beginner", "exp": "Shows a state that continues: 닫히다 ''to be closed'' → 닫혀 있어요 ''stays closed''.", "ex_ko": "수능 문제를 만드는 곳은 40일 동안 완전히 닫혀 있어요.", "ex_en": "The place where college entrance exam questions are created is completely closed for 40 days."}, {"name": "에는 (locative + topic particle)", "level": "Beginner", "exp": "Combines 에 (in) and 는 (topic). Marks location with emphasis/contrast.", "ex_ko": "이 영화에는 여러 캐릭터가 나와요.", "ex_en": "This movie features several characters."}, {"name": "~(으)ㄴ (adjective modifier)", "level": "Beginner", "exp": "Turns an adjective into a noun modifier: 많다 → 경험이 많은 강지혜 ''Kang Ji-hye, who has a lot of experience''.", "ex_ko": "한국 문학 교수 나은미, 미학 교수 예 교수, 수능 출제 경험이 많은 강지혜가 나와요.", "ex_en": "Korean literature professor Na Eun-mi, aesthetics professor Professor Ye, and Kang Ji-hye, who has a lot of experience writing CSAT questions, appear."}, {"name": "와/과 (conjunctive particle)", "level": "Beginner", "exp": "Connects two nouns in coordination. Marks ''and'' relationship between items.", "ex_ko": "또 수능 검토 위원장 박경태와 국어 출제 위원장 문주열도 나와요.", "ex_en": "Park Kyung-tae, head of the CSAT review committee, and Moon Ju-yeol, head of the Korean-language question committee, also appear."}, {"name": "도 (inclusive particle)", "level": "Beginner", "exp": "Adds inclusive meaning applied to the last item in a list. Shows these actors also appear like previously mentioned ones.", "ex_ko": "또 수능 검토 위원장 박경태와 국어 출제 위원장 문주열도 나와요.", "ex_en": "Park Kyung-tae, head of the CSAT review committee, and Moon Ju-yeol, head of the Korean-language question committee, also appear."}, {"name": "~았/었어요", "level": "Beginner", "exp": "Past tense polite declarative ending. Marks completed action. 맡다 → 맡았어요.", "ex_ko": "맹보람 역은 이선빈이 맡았어요.", "ex_en": "The role of Maeng Boram was taken by Lee Sunbin."}, {"name": "~ㄹ 수 있어요", "level": "Beginner", "exp": "Expresses possibility or ability. 보다 → 볼 수 있다 (can watch/see).", "ex_ko": "영화는 10월 28일에 전국 극장에서 볼 수 있어요.", "ex_en": "The movie can be seen in theaters nationwide on October 28th."}]}', updated_at = now() where article_id = 'mv5qxedswefn' and md5(translation) = 'e290928a6bc2f85e26690dec005f6017';
update public.article_cache set translation = '{"texts": ["The European Union has decided to cap imports of Chinese hybrid electric vehicles at 350,000 units per year, with the European Commission officially confirming the measure, which is set to take effect in December.", "Because the measure is being taken under WTO safeguard provisions, it can be implemented swiftly without the anti-dumping investigation procedures that would otherwise be required; vehicles imported above the quota will not face tariffs but will be blocked at European ports.", "Sales of Chinese battery electric and plug-in hybrid vehicles in the EU are projected to reach approximately 800,000 units this year, and the import cap is expected to halve China''s current 6% market share to around 3%.", "Chinese-branded vehicles manufactured within the EU, such as those produced in Hungary, are exempt from the quota, while EU companies producing vehicles in China will be subject to it, officials stated.", "As part of the four-year agreement signed in Beijing last week, China agreed to eliminate some tariffs on auto parts and halve duties on EU exports including footwear, olive oil, and ice cream; officials emphasized that the quota has China''s full support and that dialogue on other sectors continues.", "Amid a trade deficit with China now running at £1 billion per day, a shift in thinking is underway within the EU — policy focus is moving away from boosting exports to curbing imports, with Andrew Small of the European Council on Foreign Relations noting that China is likely to draw the EU into prolonged negotiations on other sectors."], "sentences": [{"text": "유럽연합은 중국산 하이브리드 전기차 수입량을 연간 35만 대로 제한하기로 하였습니다.", "translation": "The European Union decided to limit annual imports of Chinese hybrid electric vehicles to 350,000 units.", "vocab": [{"ko": "하이브리드", "en": "hybrid"}, {"ko": "수입량", "en": "import volume"}, {"ko": "연간", "en": "annually; per year"}, {"ko": "제한하다", "en": "to limit; to restrict"}], "analysis": [{"type": "grammar", "label": "~기로 하다", "exp": "''Decide to'': 제한하다 → 제한하기로 하였습니다 ''decided to limit''.", "example_in_sentence": "제한하기로 하였습니다"}]}, {"text": "유럽 집행위원회가 이를 공식 확인한 가운데, 해당 조치는 오는 12월부터 발효될 예정입니다.", "translation": "With the European Commission officially confirming this, the measure is scheduled to take effect starting this December.", "vocab": [{"ko": "집행위원회", "en": "executive commission; commission"}, {"ko": "공식", "en": "official; formally"}, {"ko": "가운데", "en": "amid; in the midst of"}, {"ko": "발효되다", "en": "to take effect; to come into force"}], "analysis": [{"type": "expression", "label": "~(으)ㄴ 가운데", "exp": "''Amid / as (something happened)'': 확인하다 → 확인한 가운데 ''with (the Commission) having confirmed this''.", "example_in_sentence": "확인한 가운데"}, {"type": "grammar", "label": "~(으)ㄹ 예정이다", "exp": "''Is scheduled to'': 발효되다 → 발효될 예정입니다 ''is scheduled to take effect''.", "example_in_sentence": "발효될 예정입니다"}]}, {"text": "이번 조치는 세계무역기구 긴급수입제한 규정을 근거로 하는 만큼, 반덤핑 조사 절차를 거치지 않고도 신속히 시행될 수 있습니다.", "translation": "Since this measure is based on WTO emergency import restriction regulations, it can be implemented quickly without going through anti-dumping investigation procedures.", "vocab": [{"ko": "근거", "en": "basis; ground; evidence"}, {"ko": "반덤핑", "en": "anti-dumping"}, {"ko": "절차", "en": "procedure; process"}, {"ko": "신속하다", "en": "to be swift; to be quick"}], "analysis": [{"type": "expression", "label": "~을/를 근거로 하다", "exp": "''To be based on N'': 규정을 근거로 하다 ''to be based on the rules''.", "example_in_sentence": "규정을 근거로 하는"}, {"type": "grammar", "label": "~는 만큼", "exp": "''Since / as (it is the case that)'': 근거로 하다 → 근거로 하는 만큼 ''since it is based on''.", "example_in_sentence": "근거로 하는 만큼"}, {"type": "grammar", "label": "~지 않고도", "exp": "Negation ~지 않다 + ~고도; means ''without doing'' or ''even without doing.'' Emphasizes accomplishment despite omission of a step.", "example_in_sentence": "거치지 않고도"}]}, {"text": "할당량을 초과하여 수입된 차량에는 관세가 부과되지 않는 대신, 유럽 항구 세관에서 통관이 차단됩니다.", "translation": "Vehicles imported beyond the quota will not face tariffs; instead, they will be blocked from clearing customs at European ports.", "vocab": [{"ko": "할당량", "en": "quota; allocation"}, {"ko": "초과하다", "en": "to exceed; to surpass"}, {"ko": "관세", "en": "tariff; customs duty"}, {"ko": "통관", "en": "customs clearance"}], "analysis": [{"type": "grammar", "label": "~는 대신", "exp": "Present attributive ~는 + 대신(instead); means ''instead of doing'' or ''in place of.'' Indicates substitution or alternative action.", "example_in_sentence": "부과되지 않는 대신"}, {"type": "grammar", "label": "~아/어 (-여)", "exp": "Formal written form of 해서: 초과하다 → 초과하여 수입된 차량 ''vehicles imported beyond (the quota)''.", "example_in_sentence": "초과하여"}]}, {"text": "올해 중국산 배터리 전기차 및 플러그인 하이브리드 판매량은 약 80만 대에 달할 것으로 전망됩니다.", "translation": "Sales of Chinese-made battery electric vehicles and plug-in hybrids are projected to reach approximately 800,000 units this year.", "vocab": [{"ko": "배터리", "en": "battery"}, {"ko": "플러그인", "en": "plug-in"}, {"ko": "판매량", "en": "sales volume"}, {"ko": "달하다", "en": "to reach; to amount to"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 것으로 전망되다", "exp": "''Is expected to'': 달하다 → 달할 것으로 전망됩니다 ''is projected to reach''.", "example_in_sentence": "달할 것으로 전망됩니다"}]}, {"text": "이번 수입 상한으로 인하여 현재 6%에 달하는 중국의 시장 점유율은 3%로 절반 수준에 그칠 것으로 예상됩니다.", "translation": "Because of this import cap, China''s market share, now at 6%, is expected to be cut in half to 3%.", "vocab": [{"ko": "상한", "en": "ceiling; upper limit"}, {"ko": "점유율", "en": "market share; share"}, {"ko": "그치다", "en": "to end at; to stop at"}], "analysis": [{"type": "grammar", "label": "~(으)로 인하여", "exp": "Formal ''due to; because of'': 상한으로 인하여 ''because of the (import) cap''.", "example_in_sentence": "상한으로 인하여"}, {"type": "grammar", "label": "~에 달하는", "exp": "Locative ~에 + 달하다(reach); attributive form meaning ''that reaches'' or ''that amounts to.'' Modifies noun with a specific measurement.", "example_in_sentence": "6%에 달하는"}, {"type": "expression", "label": "~에 그치다", "exp": "''To stop at / only reach (a low level)'': 절반 수준에 그칠 것 ''will stay at only half''.", "example_in_sentence": "절반 수준에 그칠"}]}, {"text": "헝가리 등 유럽연합 역내에서 생산되는 중국 브랜드 차량은 이번 할당 적용 대상에서 제외됩니다.", "translation": "Chinese-brand vehicles produced within the EU, such as in Hungary, are excluded from this quota application.", "vocab": [{"ko": "역내", "en": "within the region; intra-regional"}, {"ko": "생산되다", "en": "to be produced; to be manufactured"}, {"ko": "제외되다", "en": "to be excluded; to be exempted"}], "analysis": [{"type": "grammar", "label": "~에서 생산되는", "exp": "Locative ~에서 (from/in) + 생산되다(to be produced, passive); present attributive form modifying noun. Indicates location/agent of production.", "example_in_sentence": "역내에서 생산되는"}, {"type": "grammar", "label": "~에서 제외되다", "exp": "Locative ~에서 (from) + 제외되다(to be excluded, passive); means ''to be excluded from'' or ''to be exempted from.''", "example_in_sentence": "적용 대상에서 제외됩니다"}]}, {"text": "반면 중국 내에서 차량을 생산하는 유럽연합 기업들은 규제 대상에 포함된다고 당국은 밝혔습니다.", "translation": "On the other hand, EU companies that produce vehicles within China are included in the scope of regulation, according to authorities.", "vocab": [{"ko": "반면", "en": "on the other hand; in contrast"}, {"ko": "규제", "en": "regulation; control"}, {"ko": "포함되다", "en": "to be included; to be contained"}, {"ko": "당국", "en": "authorities; officials"}], "analysis": [{"type": "expression", "label": "~는 (noun modifier)", "exp": "Present modifier: 생산하다 → 차량을 생산하는 기업 ''companies that make cars''.", "example_in_sentence": "생산하는 유럽연합 기업들은"}, {"type": "grammar", "label": "~다고 밝히다", "exp": "Reported statement: 포함되다 → 포함된다고 밝혔습니다 ''(the authorities) said they are included''.", "example_in_sentence": "포함된다고 당국은 밝혔습니다"}]}, {"text": "지난주 베이징에서 체결된 4년 협정의 일환으로 중국은 일부 자동차 부품 관세를 폐지하고, 신발·올리브유·아이스크림 등 유럽연합산 제품에 대한 관세를 절반으로 인하하기로 합의하였습니다.", "translation": "As part of a 4-year agreement concluded in Beijing last week, China agreed to abolish tariffs on some auto parts and reduce tariffs on EU-origin products such as shoes, olive oil, and ice cream by half.", "vocab": [{"ko": "체결되다", "en": "to be signed; to be concluded"}, {"ko": "일환", "en": "part; aspect; component"}, {"ko": "폐지하다", "en": "to abolish; to eliminate"}, {"ko": "인하하다", "en": "to reduce; to lower (formal)"}], "analysis": [{"type": "expression", "label": "~의 일환으로", "exp": "Genitive ~의 + 일환(part/aspect) + ~로(as); means ''as part of'' or ''in the context of.'' Indicates component or aspect of a larger whole.", "example_in_sentence": "협정의 일환으로"}, {"type": "grammar", "label": "~기로 합의하다", "exp": "''Agree to do'': 인하하다 → 인하하기로 합의하였습니다 ''agreed to cut''.", "example_in_sentence": "인하하기로 합의하였습니다"}]}, {"text": "당국자들은 이번 할당 조치가 중국의 전폭적인 지지를 받고 있으며, 화학제품·재생에너지·가구 등 여타 품목에 대하여도 대화가 지속되고 있다고 강조하였습니다.", "translation": "Officials emphasized that this quota measure is receiving full support from China, and that dialogue is ongoing regarding other items such as chemicals, renewable energy, and furniture.", "vocab": [{"ko": "당국자", "en": "official; authority representative"}, {"ko": "전폭적", "en": "full; wholehearted; complete"}, {"ko": "지지", "en": "support; backing"}, {"ko": "지속되다", "en": "to be sustained; to continue"}], "analysis": [{"type": "grammar", "label": "~고 있으며", "exp": "''Is …ing, and'': 받다 → 받고 있으며 ''is receiving (support), and…''.", "example_in_sentence": "받고 있으며"}, {"type": "expression", "label": "~에 대하여", "exp": "Dative case marker ~에 (target/scope) + 대하여(toward/regarding); means ''regarding'' or ''concerning.'' Indicates object or target of action/discussion.", "example_in_sentence": "여타 품목에 대하여도"}]}, {"text": "유럽연합이 중국에 대하여 하루 10억 파운드의 무역 적자를 기록하고 있는 가운데, 내부에서는 인식의 전환이 이루어지고 있습니다.", "translation": "Amid the EU recording a daily trade deficit of 1 billion pounds against China, a shift in perception is taking place internally.", "vocab": [{"ko": "무역 적자", "en": "trade deficit"}, {"ko": "기록하다", "en": "to record; to register"}, {"ko": "인식", "en": "recognition; perception; awareness"}, {"ko": "전환", "en": "shift; conversion; change"}], "analysis": [{"type": "expression", "label": "~는 가운데", "exp": "''Amid / while'': 기록하고 있다 → 기록하고 있는 가운데 ''while (the EU) is running…''.", "example_in_sentence": "기록하고 있는 가운데"}, {"type": "grammar", "label": "~이/가 이루어지다", "exp": "''(Something) takes place'': 전환이 이루어지다 ''a shift happens'' → 이루어지고 있습니다 ''is happening''.", "example_in_sentence": "인식의 전환이 이루어지고 있습니다"}]}, {"text": "수출 확대를 통해 무역 불균형을 해소하려던 기존 전략에서 벗어나, 수입 억제에 초점을 맞추는 방향으로 정책 기조가 옮겨가고 있습니다.", "translation": "Policy is shifting away from the old strategy of trying to fix the trade imbalance by expanding exports, toward a focus on curbing imports.", "vocab": [{"ko": "수출 확대", "en": "export expansion; increase in exports"}, {"ko": "해소하다", "en": "to resolve; to clear; to settle"}, {"ko": "벗어나다", "en": "to get away from; to deviate from"}, {"ko": "억제", "en": "suppression; restraint; control"}], "analysis": [{"type": "grammar", "label": "~(으)려던", "exp": "''That was meant to'': 해소하다 → 해소하려던 전략 ''the strategy that was meant to resolve (the imbalance)''.", "example_in_sentence": "해소하려던 기존 전략"}, {"type": "expression", "label": "~에서 벗어나다", "exp": "Locative ~에서 (from) + 벗어나다(to escape/deviate); means ''to depart from'' or ''to break away from.'' Indicates rejection or abandonment of prior approach.", "example_in_sentence": "전략에서 벗어나"}, {"type": "expression", "label": "~에 초점을 맞추다", "exp": "Goal/target ~에 (on) + 초점(focus) + 맞추다(to adjust/align); idiomatic: ''to focus on'' or ''to direct attention to.''", "example_in_sentence": "수입 억제에 초점을 맞추는"}, {"type": "grammar", "label": "~는 방향으로", "exp": "''Toward (doing)'': 초점을 맞추는 방향으로 옮겨가다 ''shift toward focusing on''.", "example_in_sentence": "맞추는 방향으로"}]}, {"text": "유럽대외관계위원회 아시아 프로그램 책임자 앤드루 스몰은 중국이 여타 분야에서 유럽연합을 장기 협상으로 끌어들이려 할 가능성이 높다고 분석하였습니다.", "translation": "Andrew Small, director of the Asia Program at the European Council on Foreign Relations, analyzed that China likely seeks to draw the EU into prolonged negotiations in other sectors.", "vocab": [{"ko": "대외관계", "en": "foreign relations; external relations"}, {"ko": "책임자", "en": "head; director; person in charge"}, {"ko": "장기 협상", "en": "prolonged/long-term negotiations"}, {"ko": "끌어들이다", "en": "to draw in; to pull into; to involve"}], "analysis": [{"type": "grammar", "label": "~(으)려 하다", "exp": "''Try / intend to'': 끌어들이다 → 끌어들이려 할 가능성이 높다 ''is likely to try to draw in''.", "example_in_sentence": "끌어들이려 할 가능성이 높다고"}, {"type": "grammar", "label": "~(으)로 (into)", "exp": "Marks what something is drawn into: 장기 협상으로 끌어들이다 ''draw (the EU) into long negotiations''.", "example_in_sentence": "장기 협상으로 끌어들이려"}]}], "version": "s6"}', vocab = '[{"ko": "하이브리드", "en": "hybrid", "note": ""}, {"ko": "수입량", "en": "import volume", "note": ""}, {"ko": "연간", "en": "annually; per year", "note": ""}, {"ko": "제한하다", "en": "to limit; to restrict", "note": ""}, {"ko": "집행위원회", "en": "executive commission; commission", "note": ""}, {"ko": "공식", "en": "official; formally", "note": ""}, {"ko": "가운데", "en": "amid; in the midst of", "note": ""}, {"ko": "발효되다", "en": "to take effect; to come into force", "note": ""}, {"ko": "근거", "en": "basis; ground; evidence", "note": ""}, {"ko": "반덤핑", "en": "anti-dumping", "note": ""}, {"ko": "절차", "en": "procedure; process", "note": ""}, {"ko": "신속하다", "en": "to be swift; to be quick", "note": ""}, {"ko": "할당량", "en": "quota; allocation", "note": ""}, {"ko": "초과하다", "en": "to exceed; to surpass", "note": ""}, {"ko": "관세", "en": "tariff; customs duty", "note": ""}, {"ko": "통관", "en": "customs clearance", "note": ""}, {"ko": "배터리", "en": "battery", "note": ""}, {"ko": "플러그인", "en": "plug-in", "note": ""}, {"ko": "판매량", "en": "sales volume", "note": ""}, {"ko": "달하다", "en": "to reach; to amount to", "note": ""}, {"ko": "상한", "en": "ceiling; upper limit", "note": ""}, {"ko": "점유율", "en": "market share; share", "note": ""}, {"ko": "그치다", "en": "to end at; to stop at", "note": ""}, {"ko": "역내", "en": "within the region; intra-regional", "note": ""}, {"ko": "생산되다", "en": "to be produced; to be manufactured", "note": ""}, {"ko": "제외되다", "en": "to be excluded; to be exempted", "note": ""}, {"ko": "반면", "en": "on the other hand; in contrast", "note": ""}, {"ko": "규제", "en": "regulation; control", "note": ""}, {"ko": "포함되다", "en": "to be included; to be contained", "note": ""}, {"ko": "당국", "en": "authorities; officials", "note": ""}, {"ko": "체결되다", "en": "to be signed; to be concluded", "note": ""}, {"ko": "일환", "en": "part; aspect; component", "note": ""}, {"ko": "폐지하다", "en": "to abolish; to eliminate", "note": ""}, {"ko": "인하하다", "en": "to reduce; to lower (formal)", "note": ""}, {"ko": "당국자", "en": "official; authority representative", "note": ""}, {"ko": "전폭적", "en": "full; wholehearted; complete", "note": ""}, {"ko": "지지", "en": "support; backing", "note": ""}, {"ko": "지속되다", "en": "to be sustained; to continue", "note": ""}, {"ko": "무역 적자", "en": "trade deficit", "note": ""}, {"ko": "기록하다", "en": "to record; to register", "note": ""}, {"ko": "인식", "en": "recognition; perception; awareness", "note": ""}, {"ko": "전환", "en": "shift; conversion; change", "note": ""}, {"ko": "수출 확대", "en": "export expansion; increase in exports", "note": ""}, {"ko": "해소하다", "en": "to resolve; to clear; to settle", "note": ""}, {"ko": "벗어나다", "en": "to get away from; to deviate from", "note": ""}, {"ko": "억제", "en": "suppression; restraint; control", "note": ""}, {"ko": "대외관계", "en": "foreign relations; external relations", "note": ""}, {"ko": "책임자", "en": "head; director; person in charge", "note": ""}, {"ko": "장기 협상", "en": "prolonged/long-term negotiations", "note": ""}, {"ko": "끌어들이다", "en": "to draw in; to pull into; to involve", "note": ""}]', grammar = '{"patterns": [{"name": "~기로 하다", "level": "Intermediate", "exp": "''Decide to'': 제한하다 → 제한하기로 하였습니다 ''decided to limit''.", "ex_ko": "유럽연합은 중국산 하이브리드 전기차 수입량을 연간 35만 대로 제한하기로 하였습니다.", "ex_en": "The European Union decided to limit annual imports of Chinese hybrid electric vehicles to 350,000 units."}, {"name": "~(으)ㄹ 예정이다", "level": "Intermediate", "exp": "''Is scheduled to'': 발효되다 → 발효될 예정입니다 ''is scheduled to take effect''.", "ex_ko": "유럽 집행위원회가 이를 공식 확인한 가운데, 해당 조치는 오는 12월부터 발효될 예정입니다.", "ex_en": "With the European Commission officially confirming this, the measure is scheduled to take effect starting this December."}, {"name": "~는 만큼", "level": "Intermediate", "exp": "''Since / as (it is the case that)'': 근거로 하다 → 근거로 하는 만큼 ''since it is based on''.", "ex_ko": "이번 조치는 세계무역기구 긴급수입제한 규정을 근거로 하는 만큼, 반덤핑 조사 절차를 거치지 않고도 신속히 시행될 수 있습니다.", "ex_en": "Since this measure is based on WTO emergency import restriction regulations, it can be implemented quickly without going through anti-dumping investigation procedures."}, {"name": "~지 않고도", "level": "Intermediate", "exp": "Negation ~지 않다 + ~고도; means ''without doing'' or ''even without doing.'' Emphasizes accomplishment despite omission of a step.", "ex_ko": "이번 조치는 세계무역기구 긴급수입제한 규정을 근거로 하는 만큼, 반덤핑 조사 절차를 거치지 않고도 신속히 시행될 수 있습니다.", "ex_en": "Since this measure is based on WTO emergency import restriction regulations, it can be implemented quickly without going through anti-dumping investigation procedures."}, {"name": "~는 대신", "level": "Intermediate", "exp": "Present attributive ~는 + 대신(instead); means ''instead of doing'' or ''in place of.'' Indicates substitution or alternative action.", "ex_ko": "할당량을 초과하여 수입된 차량에는 관세가 부과되지 않는 대신, 유럽 항구 세관에서 통관이 차단됩니다.", "ex_en": "Vehicles imported beyond the quota will not face tariffs; instead, they will be blocked from clearing customs at European ports."}, {"name": "~아/어 (-여)", "level": "Intermediate", "exp": "Formal written form of 해서: 초과하다 → 초과하여 수입된 차량 ''vehicles imported beyond (the quota)''.", "ex_ko": "할당량을 초과하여 수입된 차량에는 관세가 부과되지 않는 대신, 유럽 항구 세관에서 통관이 차단됩니다.", "ex_en": "Vehicles imported beyond the quota will not face tariffs; instead, they will be blocked from clearing customs at European ports."}, {"name": "~(으)ㄹ 것으로 전망되다", "level": "Intermediate", "exp": "''Is expected to'': 달하다 → 달할 것으로 전망됩니다 ''is projected to reach''.", "ex_ko": "올해 중국산 배터리 전기차 및 플러그인 하이브리드 판매량은 약 80만 대에 달할 것으로 전망됩니다.", "ex_en": "Sales of Chinese-made battery electric vehicles and plug-in hybrids are projected to reach approximately 800,000 units this year."}, {"name": "~(으)로 인하여", "level": "Intermediate", "exp": "Formal ''due to; because of'': 상한으로 인하여 ''because of the (import) cap''.", "ex_ko": "이번 수입 상한으로 인하여 현재 6%에 달하는 중국의 시장 점유율은 3%로 절반 수준에 그칠 것으로 예상됩니다.", "ex_en": "Because of this import cap, China''s market share, now at 6%, is expected to be cut in half to 3%."}, {"name": "~에 달하는", "level": "Intermediate", "exp": "Locative ~에 + 달하다(reach); attributive form meaning ''that reaches'' or ''that amounts to.'' Modifies noun with a specific measurement.", "ex_ko": "이번 수입 상한으로 인하여 현재 6%에 달하는 중국의 시장 점유율은 3%로 절반 수준에 그칠 것으로 예상됩니다.", "ex_en": "Because of this import cap, China''s market share, now at 6%, is expected to be cut in half to 3%."}, {"name": "~에서 생산되는", "level": "Intermediate", "exp": "Locative ~에서 (from/in) + 생산되다(to be produced, passive); present attributive form modifying noun. Indicates location/agent of production.", "ex_ko": "헝가리 등 유럽연합 역내에서 생산되는 중국 브랜드 차량은 이번 할당 적용 대상에서 제외됩니다.", "ex_en": "Chinese-brand vehicles produced within the EU, such as in Hungary, are excluded from this quota application."}, {"name": "~에서 제외되다", "level": "Intermediate", "exp": "Locative ~에서 (from) + 제외되다(to be excluded, passive); means ''to be excluded from'' or ''to be exempted from.''", "ex_ko": "헝가리 등 유럽연합 역내에서 생산되는 중국 브랜드 차량은 이번 할당 적용 대상에서 제외됩니다.", "ex_en": "Chinese-brand vehicles produced within the EU, such as in Hungary, are excluded from this quota application."}, {"name": "~다고 밝히다", "level": "Intermediate", "exp": "Reported statement: 포함되다 → 포함된다고 밝혔습니다 ''(the authorities) said they are included''.", "ex_ko": "반면 중국 내에서 차량을 생산하는 유럽연합 기업들은 규제 대상에 포함된다고 당국은 밝혔습니다.", "ex_en": "On the other hand, EU companies that produce vehicles within China are included in the scope of regulation, according to authorities."}, {"name": "~기로 합의하다", "level": "Intermediate", "exp": "''Agree to do'': 인하하다 → 인하하기로 합의하였습니다 ''agreed to cut''.", "ex_ko": "지난주 베이징에서 체결된 4년 협정의 일환으로 중국은 일부 자동차 부품 관세를 폐지하고, 신발·올리브유·아이스크림 등 유럽연합산 제품에 대한 관세를 절반으로 인하하기로 합의하였습니다.", "ex_en": "As part of a 4-year agreement concluded in Beijing last week, China agreed to abolish tariffs on some auto parts and reduce tariffs on EU-origin products such as shoes, olive oil, and ice cream by half."}, {"name": "~고 있으며", "level": "Intermediate", "exp": "''Is …ing, and'': 받다 → 받고 있으며 ''is receiving (support), and…''.", "ex_ko": "당국자들은 이번 할당 조치가 중국의 전폭적인 지지를 받고 있으며, 화학제품·재생에너지·가구 등 여타 품목에 대하여도 대화가 지속되고 있다고 강조하였습니다.", "ex_en": "Officials emphasized that this quota measure is receiving full support from China, and that dialogue is ongoing regarding other items such as chemicals, renewable energy, and furniture."}, {"name": "~이/가 이루어지다", "level": "Intermediate", "exp": "''(Something) takes place'': 전환이 이루어지다 ''a shift happens'' → 이루어지고 있습니다 ''is happening''.", "ex_ko": "유럽연합이 중국에 대하여 하루 10억 파운드의 무역 적자를 기록하고 있는 가운데, 내부에서는 인식의 전환이 이루어지고 있습니다.", "ex_en": "Amid the EU recording a daily trade deficit of 1 billion pounds against China, a shift in perception is taking place internally."}]}', updated_at = now() where article_id = 'mv5rgzg09ids' and md5(translation) = '08b15d7385b3eeb9f2fa4db7c27487d6';
update public.article_cache set translation = '{"texts": ["A post claiming that someone''s skin improved noticeably in just one month went viral on a Korean online community, with the writer saying they had started taking inner beauty supplements after struggling with skin troubles and a damaged skin barrier.", "Inner beauty refers to a skin-care approach that involves consuming products rather than applying them topically, with gummies or supplements containing ingredients like collagen or mucin meant to improve skin from the inside out.", "Many commenters agreed that what you eat has a greater impact on your body than any topical product, with several pointing out that even the best skincare routine is useless if your nutrition and eating habits are poor.", "On the other hand, some netizens were skeptical, questioning whether the post was a covert advertisement for a specific product, and others noted that the marketing tactics seem to be getting increasingly clever.", "The demand for inner beauty products has been growing in South Korea recently, and netizens remain divided between those who believe in the products'' effects and those who suspect such posts are simply disguised ads."], "sentences": [{"text": "한 온라인 커뮤니티에 한 달 만에 피부가 눈에 띄게 좋아졌다는 글이 올라오면서 화제가 되었습니다.", "translation": "A post claiming that skin improved noticeably within a month was uploaded to an online community, becoming a hot topic.", "vocab": [{"ko": "눈에 띄다", "en": "stand out; be noticeable"}, {"ko": "올라오다", "en": "be uploaded"}, {"ko": "화제가 되다", "en": "become a topic of discussion"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "''As / when'': 올라오다 → 올라오면서 ''as (the post) went up, (it became a hot topic)''.", "example_in_sentence": "올라오면서"}, {"type": "expression", "label": "~다는 N", "exp": "Links a reported statement to a noun: 좋아졌다 + 는 글 = ''a post saying (skin) got better''.", "example_in_sentence": "좋아졌다는 글"}]}, {"text": "글쓴이는 피부 트러블과 장벽 손상으로 고민하다가 이너뷰티 제품을 먹기 시작했다고 합니다.", "translation": "The writer says that after struggling with skin trouble and a damaged skin barrier, she started taking inner-beauty products.", "vocab": [{"ko": "트러블", "en": "trouble; skin problems"}, {"ko": "장벽 손상", "en": "barrier damage"}, {"ko": "고민하다", "en": "worry; be troubled"}], "analysis": [{"type": "grammar", "label": "~다가", "exp": "One action is going on and then another follows: 고민하다 → 고민하다가 ''after worrying (for a while), (then)…''.", "example_in_sentence": "고민하다가"}, {"type": "grammar", "label": "~기 시작하다", "exp": "Auxiliary construction meaning ''begin to ~''; nominalizer ~기 + auxiliary verb 시작하다. Verb 먹다 → 먹기 시작하다.", "example_in_sentence": "먹기 시작했다"}, {"type": "grammar", "label": "~(다)고 합니다", "exp": "Reported/hearsay speech marker: conveys information indirectly or from a source. ~다고 + auxiliary 하다.", "example_in_sentence": "시작했다고 합니다"}]}, {"text": "이너뷰티란 피부에 직접 바르는 화장품 대신 먹는 방식으로 피부를 관리하는 것을 말합니다.", "translation": "Inner beauty refers to managing skin by consuming products instead of applying cosmetics directly to the skin.", "vocab": [{"ko": "바르다", "en": "apply; spread on"}, {"ko": "방식", "en": "way; method"}], "analysis": [{"type": "grammar", "label": "~는 (noun modifier)", "exp": "Present modifier: 바르다 → 바르는 화장품 ''cosmetics you put on''; 먹다 → 먹는 방식 ''a way of eating''.", "example_in_sentence": "바르는 화장품"}, {"type": "grammar", "label": "~는 것을 말하다", "exp": "''(X) means / refers to…'': 관리하다 → 관리하는 것을 말합니다 ''refers to caring for (skin)''.", "example_in_sentence": "관리하는 것을 말합니다"}]}, {"text": "콜라겐이나 뮤신 같은 성분이 들어간 젤리나 보조제를 먹으면서 피부를 속부터 개선하려는 방식입니다.", "translation": "It is a method of consuming jellies or supplements containing ingredients like collagen or mucin, attempting to improve skin from the inside.", "vocab": [{"ko": "콜라겐", "en": "collagen"}, {"ko": "뮤신", "en": "mucin"}, {"ko": "성분", "en": "ingredient; component"}, {"ko": "들어가다", "en": "be included; be contained"}], "analysis": [{"type": "grammar", "label": "~(이)나", "exp": "Particle listing alternatives; ''or''. Links 콜라겐 and 뮤신 as examples.", "example_in_sentence": "콜라겐이나 뮤신"}, {"type": "grammar", "label": "~(으)ㄴ", "exp": "Past attributive modifier; describes 젤리나 보조제. Verb 들어가다 → 들어간.", "example_in_sentence": "들어간 젤리"}, {"type": "expression", "label": "속부터 개선하다", "exp": "Improve from within/inside. 속 (inside) + particle 부터 (from) + verb 개선하다.", "example_in_sentence": "속부터 개선하려는"}, {"type": "grammar", "label": "~(으)려는", "exp": "''Trying / intending to'' as a noun modifier: 개선하다 → 개선하려는 방식 ''a way of trying to improve''.", "example_in_sentence": "개선하려는 방식"}]}, {"text": "댓글에서는 화장품보다 먹는 것이 몸에 더 큰 영향을 준다는 의견이 많았습니다.", "translation": "In the comments, there were many opinions claiming that consuming products had a greater impact on the body than cosmetics.", "vocab": [{"ko": "영향을 주다", "en": "have an impact; exert influence"}], "analysis": [{"type": "expression", "label": "~보다", "exp": "Comparative particle: ''more than ~''. Marks the reference point in comparison; 화장품보다 (more than cosmetics).", "example_in_sentence": "화장품보다"}, {"type": "expression", "label": "~는 것", "exp": "Turns a verb into a noun ''doing…'': 먹다 → 먹는 것이 ''eating (them)'' as the subject.", "example_in_sentence": "먹는 것이"}, {"type": "expression", "label": "~다는 의견", "exp": "Quoted nominal expressing reported opinion: ''~다는'' transforms a clause into a noun phrase meaning ''opinion that ~''.", "example_in_sentence": "준다는 의견"}]}, {"text": "아무리 좋은 화장품을 발라도 영양 섭취와 식습관이 무너지면 효과가 없다는 지적도 이어졌습니다.", "translation": "There was also a point raised that no matter how good the cosmetics applied, if nutrition intake and eating habits deteriorate, there is no effect.", "vocab": [{"ko": "아무리", "en": "no matter how; however much"}, {"ko": "영양 섭취", "en": "nutritional intake"}, {"ko": "식습관", "en": "eating habits"}, {"ko": "무너지다", "en": "collapse; deteriorate"}], "analysis": [{"type": "grammar", "label": "~아/어도", "exp": "Concessive conditional; ''even if, though''. Verb 바르다 → 발라도.", "example_in_sentence": "발라도"}, {"type": "grammar", "label": "~(으)면", "exp": "Conditional marker; ''if''. Verb 무너지다 → 무너지면.", "example_in_sentence": "무너지면"}, {"type": "grammar", "label": "~다는 지적", "exp": "Quoted nominal phrase: ''지적'' (point/observation) + marker 다는; expresses reported criticism or remark.", "example_in_sentence": "없다는 지적"}]}, {"text": "반면 일부 네티즌들은 이 글이 특정 제품의 마케팅이 아니냐고 의심하기도 했습니다.", "translation": "On the other hand, some netizens suspected the post might be marketing for a particular product.", "vocab": [{"ko": "반면", "en": "on the other hand; in contrast"}, {"ko": "일부", "en": "some; part of"}, {"ko": "마케팅", "en": "marketing"}, {"ko": "의심하다", "en": "suspect; doubt"}], "analysis": [{"type": "grammar", "label": "~(이) 아니냐고", "exp": "Indirect interrogative marker; embeds a yes/no question. Copula 이다 (negated 아니다) + ~냐고 (reported question).", "example_in_sentence": "아니냐고 의심하기도"}, {"type": "grammar", "label": "~기도 하다", "exp": "Auxiliary construction: ''also do ~''; adds emphatic or inclusive nuance. Verb 의심하다 → 의심하기도 했다.", "example_in_sentence": "의심하기도 했습니다"}]}, {"text": "사진 속 인물이 같은 사람인지 모르겠다거나, 광고 방식이 점점 교묘해지고 있다는 비판적인 반응도 있었습니다.", "translation": "There were also critical reactions, with some saying they couldn''t tell whether the person in the photos was the same, or that ads are getting craftier.", "vocab": [{"ko": "인물", "en": "person; figure"}, {"ko": "교묘하다", "en": "to be crafty; to be sly"}, {"ko": "비판적", "en": "critical"}], "analysis": [{"type": "grammar", "label": "~인지 모르겠다", "exp": "''Not sure whether (it is)'': 같은 사람이다 → 같은 사람인지 모르겠다 ''not sure if it''s the same person''.", "example_in_sentence": "사람인지 모르겠다"}, {"type": "grammar", "label": "~다거나", "exp": "Lists example remarks, ''(saying) … or …'': 모르겠다 → 모르겠다거나 ''(saying) they couldn''t tell, or…''.", "example_in_sentence": "모르겠다거나"}, {"type": "grammar", "label": "~다는 N", "exp": "Links a reported statement to a noun: 교묘해지고 있다 + 는 반응 ''reactions saying (ads) are getting craftier''.", "example_in_sentence": "있다는 비판적인 반응"}]}, {"text": "한국에서는 최근 피부 관리를 위해 이너뷰티 제품을 찾는 사람이 늘고 있습니다.", "translation": "In Korea, recently the number of people seeking inner beauty products for skin care has been increasing.", "vocab": [{"ko": "최근", "en": "recently"}, {"ko": "피부 관리", "en": "skin care"}, {"ko": "늘다", "en": "increase; grow"}], "analysis": [{"type": "grammar", "label": "~는 (noun modifier)", "exp": "Present modifier: 찾다 → 찾는 사람 ''people who look for''.", "example_in_sentence": "찾는 사람"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect marker; indicates ongoing action. Verb 늘다 → 늘고 있습니다.", "example_in_sentence": "늘고 있습니다"}, {"type": "expression", "label": "~을/를 위해", "exp": "Purpose/beneficiary marker; ''for the sake of, in order to''. Marks the goal of the preceding action.", "example_in_sentence": "관리를 위해"}]}, {"text": "네티즌들 사이에서는 제품의 효과를 믿는 쪽과 광고 여부를 의심하는 쪽이 서로 엇갈린 반응을 보이고 있습니다.", "translation": "Among netizens, reactions are split between those who believe the products work and those who suspect it''s an ad.", "vocab": [{"ko": "효과", "en": "effect; efficacy"}, {"ko": "광고 여부", "en": "whether it is advertising"}, {"ko": "엇갈리다", "en": "to be divided; to differ"}], "analysis": [{"type": "expression", "label": "~ 사이에서", "exp": "Among; within a group. Marks the location/scope of the action or state.", "example_in_sentence": "네티즌들 사이에서는"}, {"type": "grammar", "label": "~는 쪽", "exp": "쪽 ''side'': 믿다 → 믿는 쪽 ''those who believe''; 의심하다 → 의심하는 쪽 ''those who doubt''.", "example_in_sentence": "믿는 쪽"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect; ongoing state/action. Verb 보이다 → 보이고 있습니다.", "example_in_sentence": "보이고 있습니다"}]}], "version": "s6"}', vocab = '[{"ko": "눈에 띄다", "en": "stand out; be noticeable", "note": ""}, {"ko": "올라오다", "en": "be uploaded", "note": ""}, {"ko": "화제가 되다", "en": "become a topic of discussion", "note": ""}, {"ko": "트러블", "en": "trouble; skin problems", "note": ""}, {"ko": "장벽 손상", "en": "barrier damage", "note": ""}, {"ko": "고민하다", "en": "worry; be troubled", "note": ""}, {"ko": "바르다", "en": "apply; spread on", "note": ""}, {"ko": "방식", "en": "way; method", "note": ""}, {"ko": "콜라겐", "en": "collagen", "note": ""}, {"ko": "뮤신", "en": "mucin", "note": ""}, {"ko": "성분", "en": "ingredient; component", "note": ""}, {"ko": "들어가다", "en": "be included; be contained", "note": ""}, {"ko": "영향을 주다", "en": "have an impact; exert influence", "note": ""}, {"ko": "아무리", "en": "no matter how; however much", "note": ""}, {"ko": "영양 섭취", "en": "nutritional intake", "note": ""}, {"ko": "식습관", "en": "eating habits", "note": ""}, {"ko": "무너지다", "en": "collapse; deteriorate", "note": ""}, {"ko": "반면", "en": "on the other hand; in contrast", "note": ""}, {"ko": "일부", "en": "some; part of", "note": ""}, {"ko": "마케팅", "en": "marketing", "note": ""}, {"ko": "의심하다", "en": "suspect; doubt", "note": ""}, {"ko": "인물", "en": "person; figure", "note": ""}, {"ko": "교묘하다", "en": "to be crafty; to be sly", "note": ""}, {"ko": "비판적", "en": "critical", "note": ""}, {"ko": "최근", "en": "recently", "note": ""}, {"ko": "피부 관리", "en": "skin care", "note": ""}, {"ko": "늘다", "en": "increase; grow", "note": ""}, {"ko": "효과", "en": "effect; efficacy", "note": ""}, {"ko": "광고 여부", "en": "whether it is advertising", "note": ""}, {"ko": "엇갈리다", "en": "to be divided; to differ", "note": ""}]', grammar = '{"patterns": [{"name": "~(으)면서", "level": "Intermediate", "exp": "''As / when'': 올라오다 → 올라오면서 ''as (the post) went up, (it became a hot topic)''.", "ex_ko": "한 온라인 커뮤니티에 한 달 만에 피부가 눈에 띄게 좋아졌다는 글이 올라오면서 화제가 되었습니다.", "ex_en": "A post claiming that skin improved noticeably within a month was uploaded to an online community, becoming a hot topic."}, {"name": "~다가", "level": "Intermediate", "exp": "One action is going on and then another follows: 고민하다 → 고민하다가 ''after worrying (for a while), (then)…''.", "ex_ko": "글쓴이는 피부 트러블과 장벽 손상으로 고민하다가 이너뷰티 제품을 먹기 시작했다고 합니다.", "ex_en": "The writer says that after struggling with skin trouble and a damaged skin barrier, she started taking inner-beauty products."}, {"name": "~기 시작하다", "level": "Intermediate", "exp": "Auxiliary construction meaning ''begin to ~''; nominalizer ~기 + auxiliary verb 시작하다. Verb 먹다 → 먹기 시작하다.", "ex_ko": "글쓴이는 피부 트러블과 장벽 손상으로 고민하다가 이너뷰티 제품을 먹기 시작했다고 합니다.", "ex_en": "The writer says that after struggling with skin trouble and a damaged skin barrier, she started taking inner-beauty products."}, {"name": "~(다)고 합니다", "level": "Intermediate", "exp": "Reported/hearsay speech marker: conveys information indirectly or from a source. ~다고 + auxiliary 하다.", "ex_ko": "글쓴이는 피부 트러블과 장벽 손상으로 고민하다가 이너뷰티 제품을 먹기 시작했다고 합니다.", "ex_en": "The writer says that after struggling with skin trouble and a damaged skin barrier, she started taking inner-beauty products."}, {"name": "~는 (noun modifier)", "level": "Intermediate", "exp": "Present modifier: 바르다 → 바르는 화장품 ''cosmetics you put on''; 먹다 → 먹는 방식 ''a way of eating''.", "ex_ko": "이너뷰티란 피부에 직접 바르는 화장품 대신 먹는 방식으로 피부를 관리하는 것을 말합니다.", "ex_en": "Inner beauty refers to managing skin by consuming products instead of applying cosmetics directly to the skin."}, {"name": "~는 것을 말하다", "level": "Intermediate", "exp": "''(X) means / refers to…'': 관리하다 → 관리하는 것을 말합니다 ''refers to caring for (skin)''.", "ex_ko": "이너뷰티란 피부에 직접 바르는 화장품 대신 먹는 방식으로 피부를 관리하는 것을 말합니다.", "ex_en": "Inner beauty refers to managing skin by consuming products instead of applying cosmetics directly to the skin."}, {"name": "~(이)나", "level": "Intermediate", "exp": "Particle listing alternatives; ''or''. Links 콜라겐 and 뮤신 as examples.", "ex_ko": "콜라겐이나 뮤신 같은 성분이 들어간 젤리나 보조제를 먹으면서 피부를 속부터 개선하려는 방식입니다.", "ex_en": "It is a method of consuming jellies or supplements containing ingredients like collagen or mucin, attempting to improve skin from the inside."}, {"name": "~(으)ㄴ", "level": "Intermediate", "exp": "Past attributive modifier; describes 젤리나 보조제. Verb 들어가다 → 들어간.", "ex_ko": "콜라겐이나 뮤신 같은 성분이 들어간 젤리나 보조제를 먹으면서 피부를 속부터 개선하려는 방식입니다.", "ex_en": "It is a method of consuming jellies or supplements containing ingredients like collagen or mucin, attempting to improve skin from the inside."}, {"name": "~(으)려는", "level": "Intermediate", "exp": "''Trying / intending to'' as a noun modifier: 개선하다 → 개선하려는 방식 ''a way of trying to improve''.", "ex_ko": "콜라겐이나 뮤신 같은 성분이 들어간 젤리나 보조제를 먹으면서 피부를 속부터 개선하려는 방식입니다.", "ex_en": "It is a method of consuming jellies or supplements containing ingredients like collagen or mucin, attempting to improve skin from the inside."}, {"name": "~아/어도", "level": "Intermediate", "exp": "Concessive conditional; ''even if, though''. Verb 바르다 → 발라도.", "ex_ko": "아무리 좋은 화장품을 발라도 영양 섭취와 식습관이 무너지면 효과가 없다는 지적도 이어졌습니다.", "ex_en": "There was also a point raised that no matter how good the cosmetics applied, if nutrition intake and eating habits deteriorate, there is no effect."}, {"name": "~다는 지적", "level": "Intermediate", "exp": "Quoted nominal phrase: ''지적'' (point/observation) + marker 다는; expresses reported criticism or remark.", "ex_ko": "아무리 좋은 화장품을 발라도 영양 섭취와 식습관이 무너지면 효과가 없다는 지적도 이어졌습니다.", "ex_en": "There was also a point raised that no matter how good the cosmetics applied, if nutrition intake and eating habits deteriorate, there is no effect."}, {"name": "~(이) 아니냐고", "level": "Intermediate", "exp": "Indirect interrogative marker; embeds a yes/no question. Copula 이다 (negated 아니다) + ~냐고 (reported question).", "ex_ko": "반면 일부 네티즌들은 이 글이 특정 제품의 마케팅이 아니냐고 의심하기도 했습니다.", "ex_en": "On the other hand, some netizens suspected the post might be marketing for a particular product."}, {"name": "~기도 하다", "level": "Intermediate", "exp": "Auxiliary construction: ''also do ~''; adds emphatic or inclusive nuance. Verb 의심하다 → 의심하기도 했다.", "ex_ko": "반면 일부 네티즌들은 이 글이 특정 제품의 마케팅이 아니냐고 의심하기도 했습니다.", "ex_en": "On the other hand, some netizens suspected the post might be marketing for a particular product."}, {"name": "~인지 모르겠다", "level": "Intermediate", "exp": "''Not sure whether (it is)'': 같은 사람이다 → 같은 사람인지 모르겠다 ''not sure if it''s the same person''.", "ex_ko": "사진 속 인물이 같은 사람인지 모르겠다거나, 광고 방식이 점점 교묘해지고 있다는 비판적인 반응도 있었습니다.", "ex_en": "There were also critical reactions, with some saying they couldn''t tell whether the person in the photos was the same, or that ads are getting craftier."}, {"name": "~다거나", "level": "Intermediate", "exp": "Lists example remarks, ''(saying) … or …'': 모르겠다 → 모르겠다거나 ''(saying) they couldn''t tell, or…''.", "ex_ko": "사진 속 인물이 같은 사람인지 모르겠다거나, 광고 방식이 점점 교묘해지고 있다는 비판적인 반응도 있었습니다.", "ex_en": "There were also critical reactions, with some saying they couldn''t tell whether the person in the photos was the same, or that ads are getting craftier."}]}', updated_at = now() where article_id = 'mv5rtvhuvx18' and md5(translation) = 'ccac38c3539104ec7c0f6d82ea58483e';
update public.article_cache set translation = '{"texts": ["Barn owl chicks were ringed for the first time in Purbeck, England — 15 chicks and one adult owl, across three farmland sites.", "Ringing the birds allows researchers to track where they go and to check whether local conservation farming efforts are working.", "Farmers keep long grass and hedgerows, which provide habitat for voles and other small mammals that barn owls feed on.", "Without rings, it is hard to tell individual barn owls apart — if a bird moves to a different nest box, researchers cannot know whether it is the same bird or a new one without a ring.", "The project will run every year, and more nest boxes are planned for next year."], "sentences": [{"text": "영국 퍼벡에서 헛간올빼미 새끼에게 고리를 달았어요.", "translation": "In Purbeck, England, rings were attached to barn owl chicks.", "vocab": [{"ko": "헛간올빼미", "en": "barn owl"}, {"ko": "새끼", "en": "chick; young animal"}, {"ko": "고리", "en": "ring"}, {"ko": "달다", "en": "to attach; to put on"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. Shows completed action in casual polite style. 달다 → 달았어요.", "example_in_sentence": "달았어요"}, {"type": "grammar", "label": "에게", "exp": "Particle marking indirect object or recipient of action. Indicates the target receiving the ring.", "example_in_sentence": "새끼에게"}]}, {"text": "새끼 15마리와 어른 올빼미 1마리예요.", "translation": "15 chicks and 1 adult owl.", "vocab": [{"ko": "마리", "en": "counter for animals"}, {"ko": "어른", "en": "adult"}], "analysis": [{"type": "grammar", "label": "~예요", "exp": "Copula in casual polite style. States identity or classification. Equivalent to ''입니다'' but more casual.", "example_in_sentence": "예요"}, {"type": "grammar", "label": "와/과", "exp": "Particle connecting two nouns in a list. 새끼와 어른 = chicks and adults.", "example_in_sentence": "와"}]}, {"text": "세 곳의 농장에서 이 일을 했어요.", "translation": "This work was done at three farms.", "vocab": [{"ko": "곳", "en": "place; location"}, {"ko": "농장", "en": "farm"}, {"ko": "일", "en": "work; task"}], "analysis": [{"type": "grammar", "label": "~의", "exp": "Possessive/genitive particle. Shows ''세 곳'' belongs to or describes ''농장''.", "example_in_sentence": "곳의"}, {"type": "grammar", "label": "~에서", "exp": "Particle marking location/place where action occurs. 농장에서 일을 했어요 = did work at the farm.", "example_in_sentence": "농장에서"}, {"type": "grammar", "label": "~했어요", "exp": "Past tense of 하다 in casual polite style.", "example_in_sentence": "했어요"}]}, {"text": "고리를 달면 새가 어디로 가는지 알 수 있어요.", "translation": "If you attach a ring, you can know where the bird goes.", "vocab": [{"ko": "어디", "en": "where"}, {"ko": "알다", "en": "to know; to understand"}], "analysis": [{"type": "grammar", "label": "~(으)면", "exp": "Ending meaning ''if / when''. 달다 → 달면 ''if (you) attach''.", "example_in_sentence": "달면"}, {"type": "grammar", "label": "~는지", "exp": "Embedded question marker. Turns action into interrogative clause within main sentence. 가다 → 가는지.", "example_in_sentence": "가는지"}, {"type": "grammar", "label": "~ㄹ 수 있어요", "exp": "Potential/possibility expression. Shows ability or possibility. 알다 → 알 수 있어요.", "example_in_sentence": "알 수 있어요"}]}, {"text": "또 농장에서 하는 자연 보호 활동이 잘 되고 있는지도 볼 수 있어요.", "translation": "Also, you can see whether nature protection activities at farms are going well.", "vocab": [{"ko": "또", "en": "also; additionally"}, {"ko": "자연", "en": "nature"}, {"ko": "보호", "en": "protection"}, {"ko": "활동", "en": "activity"}], "analysis": [{"type": "grammar", "label": "~는", "exp": "Present tense relativizer modifying noun. 하는 활동 = activities that are being done.", "example_in_sentence": "하는"}, {"type": "grammar", "label": "~고 있는지", "exp": "Progressive aspect + embedded question. Shows ongoing state within interrogative clause. 되다 → 되고 있는지.", "example_in_sentence": "되고 있는지"}, {"type": "grammar", "label": "~ㄹ 수 있어요", "exp": "Potential expression showing possibility. 보다 → 볼 수 있어요.", "example_in_sentence": "볼 수 있어요"}]}, {"text": "농장 사람들은 긴 풀밭과 나무 울타리를 잘 지켜요.", "translation": "The farmers take good care of long grassy fields and wooden fences.", "vocab": [{"ko": "풀밭", "en": "grassfield; meadow"}, {"ko": "나무", "en": "tree; wood"}, {"ko": "울타리", "en": "fence"}, {"ko": "지키다", "en": "to keep; to maintain; to protect"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "Topic particle marking the subject. 사람들은 = as for farm people.", "example_in_sentence": "은"}, {"type": "grammar", "label": "~를/을", "exp": "Object particle marking direct object of action. 풀밭과 울타리를 지켜요 = maintain the grassfields and fences.", "example_in_sentence": "를"}]}, {"text": "이런 곳에 들쥐 같은 작은 동물들이 살아요.", "translation": "In such places, small animals like field mice live.", "vocab": [{"ko": "들쥐", "en": "field mouse; vole"}, {"ko": "작다", "en": "to be small"}, {"ko": "동물", "en": "animal"}, {"ko": "살다", "en": "to live; to reside"}], "analysis": [{"type": "grammar", "label": "~에", "exp": "Particle marking location where something exists/occurs. 곳에 살아요 = live in the place.", "example_in_sentence": "에"}, {"type": "expression", "label": "~ 같은", "exp": "Expression meaning ''like'' or ''such as.'' Indicates similarity or examples. 들쥐 같은 = like field mice.", "example_in_sentence": "같은"}, {"type": "grammar", "label": "~이/가", "exp": "Subject particle. After a consonant use 이: 동물들 + 이 = 동물들이 ''animals'' (who live there).", "example_in_sentence": "동물들이"}]}, {"text": "헛간올빼미는 이 작은 동물들을 먹어요.", "translation": "Barn owls eat these small animals.", "vocab": [{"ko": "먹다", "en": "to eat"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "Topic particle. 헛간올빼미는 = as for barn owls.", "example_in_sentence": "는"}, {"type": "grammar", "label": "~을/를", "exp": "Object particle marking direct object. 동물들을 먹어요 = eat the animals.", "example_in_sentence": "을"}]}, {"text": "헛간올빼미에게 고리 없이는 어떤 새인지 알기 어려워요.", "translation": "Without rings, it''s hard to tell which barn owl is which.", "vocab": [{"ko": "없이", "en": "without"}, {"ko": "어떤", "en": "what kind of; which"}, {"ko": "어렵다", "en": "to be difficult"}], "analysis": [{"type": "grammar", "label": "~에게", "exp": "Particle indicating target/recipient. 올빼미에게 = for/to the owl.", "example_in_sentence": "에게"}, {"type": "expression", "label": "~ 없이는", "exp": "Expression showing negation or absence as precondition. 고리 없이는 = without a ring (literally).", "example_in_sentence": "없이는"}, {"type": "grammar", "label": "~기 어렵다", "exp": "''Hard to do'': 알다 → 알기 어려워요 ''hard to know''.", "example_in_sentence": "알기 어려워요"}, {"type": "grammar", "label": "~어/아요", "exp": "Present tense ending in casual polite style. 어렵다 → 어려워요.", "example_in_sentence": "어려워요"}]}, {"text": "새가 다른 둥지 상자로 가도 같은 새인지 새로운 새인지 몰라요.", "translation": "Even if the bird goes to a different nest box, you don''t know if it is the same bird or a new bird.", "vocab": [{"ko": "다르다", "en": "to be different; other"}, {"ko": "둥지", "en": "nest"}, {"ko": "상자", "en": "box"}, {"ko": "같다", "en": "to be the same"}], "analysis": [{"type": "grammar", "label": "~아/어도", "exp": "Ending meaning ''even if'': 가다 → 가도 ''even if (it) goes''.", "example_in_sentence": "가도"}, {"type": "grammar", "label": "~인지 ~인지", "exp": "Repeated embedded question marker showing alternatives/disjunction. 새인지... 새인지 = whether... or whether...", "example_in_sentence": "인지 새로운 새인지"}, {"type": "grammar", "label": "~어/아요", "exp": "Present tense in casual polite style. 모르다 → 몰라요.", "example_in_sentence": "몰라요"}]}, {"text": "고리가 있으면 알 수 있어요.", "translation": "If there is a ring, you can know.", "vocab": [{"ko": "있다", "en": "to exist; to have"}], "analysis": [{"type": "grammar", "label": "~이/가", "exp": "Subject particle. After a vowel use 가: 고리 + 가 = 고리가 ''a ring''.", "example_in_sentence": "고리가"}, {"type": "grammar", "label": "~(으)면", "exp": "Ending meaning ''if''. After a consonant use 으면: 있다 → 있으면 ''if there is''.", "example_in_sentence": "있으면"}, {"type": "grammar", "label": "~ㄹ 수 있어요", "exp": "Potential expression. 알 수 있어요 = can know.", "example_in_sentence": "알 수 있어요"}]}, {"text": "이 프로젝트는 매년 계속될 거예요.", "translation": "This project will continue every year.", "vocab": [{"ko": "프로젝트", "en": "project"}, {"ko": "매년", "en": "every year; annually"}, {"ko": "계속되다", "en": "to continue; to go on"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "Topic particle. 프로젝트는 = as for the project.", "example_in_sentence": "는"}, {"type": "grammar", "label": "~ㄹ 거예요", "exp": "Future tense in casual polite style. 계속되다 → 계속될 거예요 = will continue.", "example_in_sentence": "계속될 거예요"}]}, {"text": "내년에는 둥지 상자를 더 많이 만들 거예요.", "translation": "Next year, we will make more nest boxes.", "vocab": [{"ko": "내년", "en": "next year"}, {"ko": "둥지", "en": "nest"}, {"ko": "상자", "en": "box"}, {"ko": "많다", "en": "to be many; to be much"}], "analysis": [{"type": "grammar", "label": "~에는", "exp": "Particle marking time when action occurs with topical emphasis. 내년에는 = as for next year.", "example_in_sentence": "에는"}, {"type": "grammar", "label": "~를", "exp": "Object particle. 상자를 만들 = make the boxes.", "example_in_sentence": "를"}, {"type": "grammar", "label": "더", "exp": "Adverb meaning ''more.'' Modifies adjective/verb. 더 많이 = more abundantly.", "example_in_sentence": "더"}, {"type": "grammar", "label": "~ㄹ 거예요", "exp": "Future tense in casual polite style. 만들다 → 만들 거예요.", "example_in_sentence": "만들 거예요"}]}], "version": "s6"}', vocab = '[{"ko": "헛간올빼미", "en": "barn owl", "note": ""}, {"ko": "새끼", "en": "chick; young animal", "note": ""}, {"ko": "고리", "en": "ring", "note": ""}, {"ko": "달다", "en": "to attach; to put on", "note": ""}, {"ko": "마리", "en": "counter for animals", "note": ""}, {"ko": "어른", "en": "adult", "note": ""}, {"ko": "곳", "en": "place; location", "note": ""}, {"ko": "농장", "en": "farm", "note": ""}, {"ko": "일", "en": "work; task", "note": ""}, {"ko": "어디", "en": "where", "note": ""}, {"ko": "알다", "en": "to know; to understand", "note": ""}, {"ko": "또", "en": "also; additionally", "note": ""}, {"ko": "자연", "en": "nature", "note"