update public.article_cache set translation = '{"texts": ["The Korean Business Research Institute announced this month''s brand reputation rankings for variety shows, based on big data collected from September 4 to October 4 across 50 programs.", "''How Do You Play?'' ranked first with a brand reputation index of 3,524,700.", "''My Little Old Boy'' came in second with an index of 3,005,550, while ''You Quiz on the Block'' placed third at 2,942,980, up 3.34% from September.", "''Radio Star'' ranked fourth at 2,856,475, up 13.77% from last month, and ''The Manager'' rounded out the top five at 2,789,868, a 14.57% increase from September."], "sentences": [{"text": "한국기업평판연구소가 이번 달 예능 프로그램 브랜드 평판 순위를 발표했어요.", "translation": "The Korea Corporate Reputation Research Institute announced this month''s entertainment program brand reputation rankings.", "vocab": [{"ko": "발표하다", "en": "announce"}, {"ko": "브랜드 평판", "en": "brand reputation"}, {"ko": "순위", "en": "ranking"}], "analysis": []}, {"text": "9월 4일부터 10월 4일까지 모은 빅데이터로 50개 프로그램을 분석했어요.", "translation": "They analyzed 50 programs using big data collected from September 4 to October 4.", "vocab": [{"ko": "모으다", "en": "collect"}, {"ko": "빅데이터", "en": "big data"}, {"ko": "분석하다", "en": "analyze"}], "analysis": [{"type": "grammar", "label": "~부터 ~까지", "exp": "Temporal range marker: ''from X to Y''. 부터 marks start point, 까지 marks endpoint.", "example_in_sentence": "9월 4일부터 10월 4일까지"}, {"type": "grammar", "label": "~(으)로 (instrumental particle)", "exp": "Marks means/material used for action. Here: means by which analysis was done.", "example_in_sentence": "빅데이터로"}, {"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier: 모으다 → 모은 빅데이터 ''big data (that was) collected''.", "example_in_sentence": "모은 빅데이터"}]}, {"text": "1위는 ''놀면 뭐하니?''예요.", "translation": "First place goes to ''How Do You Play?''.", "vocab": [{"ko": "1위", "en": "1st place / first rank"}], "analysis": []}, {"text": "이 프로그램의 브랜드 평판 지수는 3,524,700이에요.", "translation": "This program''s brand reputation index is 3,524,700.", "vocab": [{"ko": "지수", "en": "index"}], "analysis": []}, {"text": "2위는 ''미운 우리 새끼''예요.", "translation": "Second place goes to ''My Little Old Boy''.", "vocab": [{"ko": "2위", "en": "2nd place / second rank"}], "analysis": []}, {"text": "브랜드 평판 지수는 3,005,550이에요.", "translation": "The brand reputation index is 3,005,550.", "vocab": [], "analysis": []}, {"text": "3위는 ''유 퀴즈 온 더 블록''이에요.", "translation": "Third place is ''You Quiz on the Block''.", "vocab": [{"ko": "3위", "en": "3rd place / third rank"}], "analysis": []}, {"text": "지수는 2,942,980으로 9월보다 3.34% 올랐어요.", "translation": "Its index was 2,942,980, up 3.34% from September.", "vocab": [{"ko": "오르다", "en": "rise / go up / increase"}], "analysis": [{"type": "grammar", "label": "~(으)로 (at a figure)", "exp": "Here (으)로 gives a figure and continues the sentence: 2,942,980으로 ''at 2,942,980, (it rose…)''.", "example_in_sentence": "2,942,980으로"}, {"type": "grammar", "label": "~보다 (comparative particle)", "exp": "Marks comparison object. ''more than X / compared to X''.", "example_in_sentence": "9월보다"}]}, {"text": "4위는 ''라디오스타''예요.", "translation": "Fourth place is ''Radio Star''.", "vocab": [{"ko": "4위", "en": "4th place / fourth rank"}], "analysis": []}, {"text": "지수는 2,856,475로 지난달보다 13.77% 올랐어요.", "translation": "Its index was 2,856,475, up 13.77% from last month.", "vocab": [{"ko": "지난달", "en": "last month"}], "analysis": [{"type": "grammar", "label": "~(으)로 (at a figure)", "exp": "Gives a figure and continues the sentence: 2,856,475로 ''at 2,856,475, (it rose…)''.", "example_in_sentence": "2,856,475로"}, {"type": "grammar", "label": "~보다", "exp": "Comparative particle: ''compared to / more than''.", "example_in_sentence": "지난달보다"}]}, {"text": "5위는 ''사장님 귀는 당나귀 귀''로 브랜드 평판 지수는 2,789,868이에요.", "translation": "Fifth place is ''Boss''s Ears are Donkey''s Ears'' with a brand reputation index of 2,789,868.", "vocab": [], "analysis": [{"type": "grammar", "label": "~(으)로 (being; and)", "exp": "(으)로 ''as / being'' continues the sentence: 5위는 ''…귀''로, 지수는 … ''fifth is …, with an index of …''.", "example_in_sentence": "''사장님 귀는 당나귀 귀''로"}]}, {"text": "이 프로그램은 9월보다 14.57% 올랐어요.", "translation": "This program rose 14.57% compared to September.", "vocab": [], "analysis": [{"type": "grammar", "label": "~보다", "exp": "Comparative particle: ''compared to / more than''.", "example_in_sentence": "9월보다"}]}], "version": "s6"}', vocab = '[{"ko": "발표하다", "en": "announce", "note": ""}, {"ko": "브랜드 평판", "en": "brand reputation", "note": ""}, {"ko": "순위", "en": "ranking", "note": ""}, {"ko": "모으다", "en": "collect", "note": ""}, {"ko": "빅데이터", "en": "big data", "note": ""}, {"ko": "분석하다", "en": "analyze", "note": ""}, {"ko": "1위", "en": "1st place / first rank", "note": ""}, {"ko": "지수", "en": "index", "note": ""}, {"ko": "2위", "en": "2nd place / second rank", "note": ""}, {"ko": "3위", "en": "3rd place / third rank", "note": ""}, {"ko": "오르다", "en": "rise / go up / increase", "note": ""}, {"ko": "4위", "en": "4th place / fourth rank", "note": ""}, {"ko": "지난달", "en": "last month", "note": ""}]', grammar = '{"patterns": [{"name": "~부터 ~까지", "level": "Intermediate", "exp": "Temporal range marker: ''from X to Y''. 부터 marks start point, 까지 marks endpoint.", "ex_ko": "9월 4일부터 10월 4일까지 모은 빅데이터로 50개 프로그램을 분석했어요.", "ex_en": "They analyzed 50 programs using big data collected from September 4 to October 4."}, {"name": "~(으)로 (instrumental particle)", "level": "Intermediate", "exp": "Here (으)로 gives a figure and continues the sentence: 2,942,980으로 ''at 2,942,980, (it rose…)''.", "ex_ko": "9월 4일부터 10월 4일까지 모은 빅데이터로 50개 프로그램을 분석했어요.", "ex_en": "They analyzed 50 programs using big data collected from September 4 to October 4."}, {"name": "~(으)ㄴ (past modifier)", "level": "Intermediate", "exp": "Past modifier: 모으다 → 모은 빅데이터 ''big data (that was) collected''.", "ex_ko": "9월 4일부터 10월 4일까지 모은 빅데이터로 50개 프로그램을 분석했어요.", "ex_en": "They analyzed 50 programs using big data collected from September 4 to October 4."}, {"name": "~보다 (comparative particle)", "level": "Intermediate", "exp": "Marks comparison object. ''more than X / compared to X''.", "ex_ko": "지수는 2,942,980으로 9월보다 3.34% 올랐어요.", "ex_en": "Its index was 2,942,980, up 3.34% from September."}]}', updated_at = now() where article_id = 'mvr6pjv82sy3' and md5(translation) = '2cd701d7e5acc673215fc7651444da4c';
